// SCOUT:TESTS:BEGIN
#[cfg(test)]
mod scout_change_authority_tests {
    use super::*;
    use ::anchor_lang::AnchorDeserialize;

    fn read_state(fixture: &MarinadeFinanceFixture) -> marinade_finance::types::State {
        let account = fixture.ctx.svm.get_account(&fixture.state).unwrap();
        assert_eq!(
            &account.data[..marinade_finance::state::State::DISCRIMINATOR_LEN],
            marinade_finance::state::State::DISCRIMINATOR
        );
        let mut body = &account.data[marinade_finance::state::State::DISCRIMINATOR_LEN..];
        marinade_finance::types::State::deserialize(&mut body).unwrap()
    }

    #[test]
    fn change_authority_succeeds_with_minted_state_and_varied_data() {
        let mut fixture = MarinadeFinanceFixture::setup();
        for _ in 0..32 {
            assert!(fixture.action_change_authority());
            assert_eq!(read_state(&fixture).admin_authority, fixture.payer.pubkey());
        }
    }

    #[test]
    fn change_authority_rejects_wrong_admin_authority() {
        let mut fixture = MarinadeFinanceFixture::setup();
        let wrong_admin = Keypair::new();
        fixture
            .ctx
            .create_account()
            .pubkey(wrong_admin.pubkey())
            .lamports(1_000_000_000)
            .owner(system_program::ID)
            .create()
            .unwrap();
        let result = fixture
            .ctx
            .program(fixture.program_id)
            .call(instruction::ChangeAuthority {
                data: scout_change_authority_data(0, wrong_admin.pubkey()),
            })
            .accounts(accounts::ChangeAuthority {
                state: fixture.state,
                admin_authority: wrong_admin.pubkey(),
            })
            .signers(&[&wrong_admin])
            .send()
            .map(|outcome| outcome.is_success())
            .unwrap_or(false);
        assert!(!result);
        assert_eq!(read_state(&fixture).admin_authority, fixture.payer.pubkey());
    }
}

#[cfg(test)]
mod add_validator_setup_tests {
    use super::*;

    fn send_add_validator(
        fixture: &mut MarinadeFinanceFixture,
        validator_vote: Pubkey,
        duplication_flag: Pubkey,
    ) -> crucible_test_context::TxOutcome {
        let payer = fixture.payer.clone();
        fixture
            .ctx
            .program(fixture.program_id)
            .call(instruction::AddValidator { score: 10 })
            .accounts(accounts::AddValidator {
                state: fixture.state,
                manager_authority: payer.pubkey(),
                validator_list: fixture.validator_list,
                validator_vote,
                duplication_flag,
                rent_payer: payer.pubkey(),
                clock: crucible_fuzzer::anchor_lang::solana_program::sysvar::clock::ID,
                rent: crucible_fuzzer::anchor_lang::solana_program::sysvar::rent::ID,
                system_program: system_program::ID,
            })
            .signers(&[&*payer])
            .send()
            .unwrap()
    }

    #[test]
    fn add_validator_reaches_real_instruction_from_fresh_setup() {
        let mut fixture = MarinadeFinanceFixture::setup();
        let validator_vote = Pubkey::new_unique();
        let (duplication_flag, _) = Pubkey::find_program_address(
            &[
                fixture.state.as_ref(),
                SCOUT_DUPLICATE_FLAG_SEED,
                validator_vote.as_ref(),
            ],
            &fixture.program_id,
        );
        let outcome = send_add_validator(&mut fixture, validator_vote, duplication_flag);
        assert!(
            outcome
                .logs()
                .iter()
                .any(|line| line.contains("Instruction: AddValidator")),
            "add_validator did not dispatch far enough to execute the target instruction: {:?}",
            outcome
        );
    }

    #[test]
    fn add_validator_wrong_duplication_flag_fails_seed_constraint() {
        let mut fixture = MarinadeFinanceFixture::setup();
        let outcome = send_add_validator(
            &mut fixture,
            Pubkey::new_unique(),
            Pubkey::new_unique(),
        );
        assert!(!outcome.is_success(), "wrong duplication flag unexpectedly succeeded");
        assert!(
            outcome
                .logs()
                .iter()
                .any(|line| line.contains("ConstraintSeeds")),
            "wrong duplication flag should fail Anchor's seeds check: {:?}",
            outcome
        );
    }
}

#[cfg(all(test, feature = "scout_orphaned_tests"))]
mod remove_validator_setup_glue_tests {
    use super::*;

    fn send_remove_validator(fixture: &mut MarinadeFinanceFixture) -> bool {
        fixture.ctx
            .program(fixture.program_id)
            .call(instruction::RemoveValidator {
                index: 0,
                validator_vote: fixture.remove_validator_vote,
            })
            .accounts(accounts::RemoveValidator {
                state: fixture.remove_state,
                manager_authority: fixture.payer.pubkey(),
                validator_list: fixture.remove_validator_list,
                duplication_flag: fixture.remove_duplication_flag,
                operational_sol_account: fixture.remove_operational_sol_account,
            })
            .signers(&[&*fixture.payer])
            .send()
            .map(|outcome| outcome.is_success())
            .unwrap_or(false)
    }

    fn remint_remove_state(
        fixture: &mut MarinadeFinanceFixture,
        paused: bool,
        delinquent_upgrader: marinade_finance::types::DelinquentUpgraderState,
    ) {
        let state_data = scout_remove_validator_state_data(
            fixture.remove_validator_list,
            fixture.payer.pubkey(),
            fixture.remove_operational_sol_account,
            paused,
            delinquent_upgrader,
        );
        fixture.ctx
            .create_account()
            .pubkey(fixture.remove_state)
            .owner(fixture.program_id)
            .data(&state_data)
            .create()
            .unwrap();
    }

    fn remint_remove_validator_list(
        fixture: &mut MarinadeFinanceFixture,
        record: marinade_finance::types::ValidatorRecord,
    ) {
        let validator_list_data = scout_validator_list_data(&[record]);
        fixture.ctx
            .create_account()
            .pubkey(fixture.remove_validator_list)
            .owner(fixture.program_id)
            .data(&validator_list_data)
            .create()
            .unwrap();
    }

    #[test]
    fn remove_validator_reaches_process_and_removes_record() {
        let mut fixture = MarinadeFinanceFixture::setup();
        assert!(fixture.action_remove_validator());
    }

    #[test]
    fn remove_validator_rejects_paused_state_guard() {
        let mut fixture = MarinadeFinanceFixture::setup();
        remint_remove_state(
            &mut fixture,
            true,
            marinade_finance::types::DelinquentUpgraderState::Done,
        );
        assert!(!send_remove_validator(&mut fixture));
    }

    #[test]
    fn remove_validator_rejects_incomplete_delinquent_upgrader_guard() {
        let mut fixture = MarinadeFinanceFixture::setup();
        remint_remove_state(
            &mut fixture,
            false,
            marinade_finance::types::DelinquentUpgraderState::IteratingStakes {
                visited_count: 0,
                total_active_balance: 0,
                total_delinquent_balance: 0,
            },
        );
        assert!(!send_remove_validator(&mut fixture));
    }

    #[test]
    fn remove_validator_rejects_wrong_record_duplication_flag_guard() {
        let mut fixture = MarinadeFinanceFixture::setup();
        let wrong_bump = scout_alternate_valid_duplication_flag_bump(
            fixture.remove_state,
            fixture.remove_validator_vote,
            fixture.program_id,
            fixture.remove_duplication_flag_bump,
        );
        let wrong_record = scout_validator_record_with_bump(
            fixture.remove_validator_vote,
            SCOUT_REMOVE_VALIDATOR_SCORE,
            wrong_bump,
        );
        remint_remove_validator_list(&mut fixture, wrong_record);
        assert!(!send_remove_validator(&mut fixture));
    }
}

#[cfg(all(test, feature = "scout_orphaned_tests"))]
mod deposit_setup_glue_tests {
    use super::*;

    fn send_deposit(f: &mut MarinadeFinanceFixture, lamports: u64) -> bool {
        f.ctx
            .program(f.program_id)
            .call(instruction::Deposit { lamports })
            .accounts(accounts::Deposit {
                state: f.state,
                msol_mint: f.msol_mint,
                liq_pool_sol_leg_pda: f.liq_pool_sol_leg_pda,
                liq_pool_msol_leg: f.liq_pool_msol_leg,
                liq_pool_msol_leg_authority: f.liq_pool_msol_leg_authority,
                reserve_pda: f.reserve_pda,
                transfer_from: f.payer.pubkey(),
                mint_to: f.mint_to,
                msol_mint_authority: f.msol_mint_authority,
                system_program: system_program::ID,
                token_program: crucible_fuzzer::anchor_spl::token::ID,
            })
            .signers(&[&*f.payer])
            .send()
            .map(|o| o.is_success())
            .unwrap_or(false)
    }

    fn rewrite_state(
        f: &mut MarinadeFinanceFixture,
        paused: bool,
        staking_sol_cap: u64,
        msol_supply: u64,
    ) {
        let state = scout_deposit_state(
            f.payer.pubkey(),
            f.program_id,
            f.state,
            f.msol_mint,
            f.liq_pool_msol_leg,
            paused,
            staking_sol_cap,
            msol_supply,
        );
        let data = scout_state_data(&state);
        f.ctx.create_account()
            .pubkey(f.state)
            .owner(f.program_id)
            .data(&data)
            .create()
            .unwrap();
    }

    fn rewrite_pool_msol_leg(f: &mut MarinadeFinanceFixture, amount: u64) {
        f.ctx.create_token_account()
            .pubkey(f.liq_pool_msol_leg)
            .mint(f.msol_mint)
            .token_owner(f.liq_pool_msol_leg_authority)
            .amount(amount)
            .create()
            .unwrap();
    }

    #[test]
    fn deposit_action_reaches_process_from_fresh_setup() {
        let mut f = MarinadeFinanceFixture::setup();
        assert!(f.action_deposit());
    }

    #[test]
    fn deposit_fully_filled_from_liq_pool_skips_reserve_and_mint() {
        let mut f = MarinadeFinanceFixture::setup();
        assert!(send_deposit(&mut f, 10_000_000));
    }

    #[test]
    fn deposit_partially_filled_mints_new_msol_and_tops_up_reserve() {
        let mut f = MarinadeFinanceFixture::setup();
        assert!(send_deposit(&mut f, 600_000_000));
    }

    #[test]
    fn deposit_skips_liq_pool_swap_when_pool_leg_is_empty() {
        let mut f = MarinadeFinanceFixture::setup();
        rewrite_pool_msol_leg(&mut f, 0);
        assert!(send_deposit(&mut f, 10_000_000));
    }

    #[test]
    fn deposit_rejects_when_program_is_paused() {
        let mut f = MarinadeFinanceFixture::setup();
        rewrite_state(&mut f, true, u64::MAX, 0);
        assert!(!send_deposit(&mut f, 10_000_000));
    }

    #[test]
    fn deposit_rejects_amount_below_min_deposit() {
        let mut f = MarinadeFinanceFixture::setup();
        assert!(!send_deposit(&mut f, 0));
    }

    #[test]
    fn deposit_rejects_when_user_has_insufficient_funds() {
        let mut f = MarinadeFinanceFixture::setup();
        assert!(!send_deposit(&mut f, u64::MAX));
    }

    #[test]
    fn deposit_rejects_when_msol_mint_supply_exceeds_registered_supply() {
        let mut f = MarinadeFinanceFixture::setup();
        f.ctx.create_mint()
            .pubkey(f.msol_mint)
            .mint_authority(f.msol_mint_authority)
            .supply(1)
            .decimals(9)
            .freeze_authority(None)
            .create()
            .unwrap();
        assert!(!send_deposit(&mut f, 10_000_000));
    }

    #[test]
    fn deposit_rejects_when_staking_sol_cap_is_exceeded() {
        let mut f = MarinadeFinanceFixture::setup();
        rewrite_state(&mut f, false, 1, 0);
        assert!(!send_deposit(&mut f, 600_000_000));
    }
}

#[cfg(all(test, feature = "scout_orphaned_tests"))]
mod set_validator_score_tests {
    use super::*;

    #[test]
    fn set_validator_score_updates_minted_validator() {
        let mut f = MarinadeFinanceFixture::setup();
        assert!(f.action_set_validator_score(1234));

        let state = f
            .ctx
            .read_anchor_account::<marinade_finance::state::State>(&f.state)
            .unwrap();
        assert_eq!(state.validator_system.total_validator_score, 1234);

        let validator_list = f.ctx.read_account(&f.validator_list).unwrap();
        let record =
            <marinade_finance::types::ValidatorRecord as anchor_lang::AnchorDeserialize>::deserialize(
                &mut &validator_list.data[8..],
            )
            .unwrap();
        assert_eq!(record.validator_account, f.validator_vote);
        assert_eq!(record.score, 1234);
    }
}

#[cfg(all(test, feature = "scout_orphaned_tests"))]
mod order_unstake_setup_glue_tests {
    use super::*;
    use ::anchor_lang::AnchorDeserialize;

    #[test]
    fn order_unstake_reaches_process_and_initializes_ticket() {
        let mut fixture = MarinadeFinanceFixture::setup();

        assert!(fixture.action_order_unstake());

        let ticket_account = fixture
            .ctx
            .read_account(&fixture.order_unstake_new_ticket_account)
            .unwrap();
        assert_eq!(
            &ticket_account.data[..marinade_finance::state::TicketAccountData::DISCRIMINATOR_LEN],
            marinade_finance::state::TicketAccountData::DISCRIMINATOR
        );
        let mut ticket_body =
            &ticket_account.data[marinade_finance::state::TicketAccountData::DISCRIMINATOR_LEN..];
        let ticket =
            marinade_finance::state::TicketAccountData::deserialize(&mut ticket_body).unwrap();
        assert_eq!(ticket.state_address, fixture.order_unstake_state);
        assert_eq!(ticket.beneficiary, fixture.payer.pubkey());
        assert_eq!(ticket.lamports_amount, SCOUT_ORDER_UNSTAKE_SOL_VALUE);
    }
}

#[cfg(test)]
mod add_validator_zero_space_init_wall_tests {
    use super::*;

    #[test]
    fn add_validator_correct_pda_dispatches_but_stops_before_process() {
        let mut fixture = MarinadeFinanceFixture::setup();
        let validator_vote = Pubkey::new_unique();
        let (duplication_flag, _) = Pubkey::find_program_address(
            &[
                fixture.state.as_ref(),
                SCOUT_DUPLICATE_FLAG_SEED,
                validator_vote.as_ref(),
            ],
            &fixture.program_id,
        );
        let payer = fixture.payer.clone();
        let outcome = fixture
            .ctx
            .program(fixture.program_id)
            .call(instruction::AddValidator { score: 10 })
            .accounts(accounts::AddValidator {
                state: fixture.state,
                manager_authority: payer.pubkey(),
                validator_list: fixture.validator_list,
                validator_vote,
                duplication_flag,
                rent_payer: payer.pubkey(),
                clock: crucible_fuzzer::anchor_lang::solana_program::sysvar::clock::ID,
                rent: crucible_fuzzer::anchor_lang::solana_program::sysvar::rent::ID,
                system_program: system_program::ID,
            })
            .signers(&[&*payer])
            .send()
            .unwrap();
        assert!(
            outcome
                .logs()
                .iter()
                .any(|line| line.contains("Instruction: AddValidator")),
            "add_validator did not dispatch: {:?}",
            outcome
        );
        assert!(
            !outcome
                .logs()
                .iter()
                .any(|line| line.contains("Add validator ")),
            "add_validator unexpectedly reached process(): {:?}",
            outcome
        );
        assert!(
            !outcome.is_success(),
            "zero-space duplication_flag init unexpectedly succeeded"
        );
    }
}

#[cfg(test)]
mod set_validator_score_guard_tests {
    use super::*;

    fn send_set_validator_score(
        fixture: &mut MarinadeFinanceFixture,
        manager: &Keypair,
        index: u32,
        validator_vote: Pubkey,
        score: u32,
    ) -> bool {
        fixture
            .ctx
            .program(fixture.program_id)
            .call(instruction::SetValidatorScore {
                index,
                validator_vote,
                score,
            })
            .accounts(accounts::SetValidatorScore {
                state: fixture.state,
                manager_authority: manager.pubkey(),
                validator_list: fixture.validator_list,
            })
            .signers(&[manager])
            .send()
            .map(|outcome| outcome.is_success())
            .unwrap_or(false)
    }

    fn rewrite_set_validator_score_state(
        fixture: &mut MarinadeFinanceFixture,
        state: marinade_finance::state::State,
    ) {
        let state_data = scout_anchor_account_data(
            marinade_finance::state::State::DISCRIMINATOR,
            &state,
        );
        fixture
            .ctx
            .create_account()
            .pubkey(fixture.state)
            .owner(fixture.program_id)
            .data(&state_data)
            .create()
            .unwrap();
    }

    fn read_set_validator_score_state(
        fixture: &MarinadeFinanceFixture,
    ) -> marinade_finance::state::State {
        fixture
            .ctx
            .read_anchor_account::<marinade_finance::state::State>(&fixture.state)
            .unwrap()
    }

    #[test]
    fn set_validator_score_rejects_paused_state_guard() {
        let mut fixture = MarinadeFinanceFixture::setup();
        let mut state = read_set_validator_score_state(&fixture);
        state.paused = true;
        rewrite_set_validator_score_state(&mut fixture, state);
        let manager = fixture.payer.clone();
        let validator_vote = fixture.validator_vote;

        assert!(!send_set_validator_score(
            &mut fixture,
            &manager,
            0,
            validator_vote,
            4321,
        ));
    }

    #[test]
    fn set_validator_score_rejects_wrong_validator_vote_guard() {
        let mut fixture = MarinadeFinanceFixture::setup();
        let manager = fixture.payer.clone();

        assert!(!send_set_validator_score(
            &mut fixture,
            &manager,
            0,
            Pubkey::new_unique(),
            4321,
        ));
    }

    #[test]
    fn set_validator_score_rejects_out_of_bounds_validator_index_guard() {
        let mut fixture = MarinadeFinanceFixture::setup();
        let manager = fixture.payer.clone();
        let validator_vote = fixture.validator_vote;

        assert!(!send_set_validator_score(
            &mut fixture,
            &manager,
            1,
            validator_vote,
            4321,
        ));
    }

    #[test]
    fn set_validator_score_rejects_wrong_manager_authority_constraint() {
        let mut fixture = MarinadeFinanceFixture::setup();
        let wrong_manager = Keypair::new();
        let validator_vote = fixture.validator_vote;
        fixture
            .ctx
            .create_account()
            .pubkey(wrong_manager.pubkey())
            .lamports(1_000_000_000)
            .owner(system_program::ID)
            .create()
            .unwrap();

        assert!(!send_set_validator_score(
            &mut fixture,
            &wrong_manager,
            0,
            validator_vote,
            4321,
        ));
    }
}

#[cfg(test)]
mod order_unstake_guard_tests {
    use super::*;

    fn remint_order_unstake_state(
        fixture: &mut MarinadeFinanceFixture,
        paused: bool,
        min_withdraw: u64,
    ) {
        let mut state = scout_order_unstake_state(
            fixture.payer.pubkey(),
            fixture.program_id,
            fixture.order_unstake_state,
            fixture.order_unstake_msol_mint,
        );
        state.paused = paused;
        state.min_withdraw = min_withdraw;
        let state_data = scout_anchor_account_data(
            marinade_finance::state::State::DISCRIMINATOR,
            &state,
        );
        fixture
            .ctx
            .create_account()
            .pubkey(fixture.order_unstake_state)
            .owner(fixture.program_id)
            .data(&state_data)
            .create()
            .unwrap();
    }

    fn remint_order_unstake_source(
        fixture: &mut MarinadeFinanceFixture,
        delegate: Option<Pubkey>,
        delegated_amount: u64,
        amount: u64,
    ) {
        fixture
            .ctx
            .create_token_account()
            .pubkey(fixture.order_unstake_burn_msol_from)
            .mint(fixture.order_unstake_msol_mint)
            .token_owner(fixture.payer.pubkey())
            .delegate(delegate)
            .delegated_amount(delegated_amount)
            .amount(amount)
            .create()
            .unwrap();
    }

    fn fund_system_signer(fixture: &mut MarinadeFinanceFixture, signer: &Keypair) {
        fixture
            .ctx
            .create_account()
            .pubkey(signer.pubkey())
            .lamports(1_000_000_000)
            .owner(system_program::ID)
            .create()
            .unwrap();
    }

    fn send_order_unstake_with_payer(
        fixture: &mut MarinadeFinanceFixture,
        msol_amount: u64,
    ) -> crucible_test_context::TxOutcome {
        let payer = fixture.payer.clone();
        fixture
            .ctx
            .program(fixture.program_id)
            .call(instruction::OrderUnstake { msol_amount })
            .accounts(accounts::OrderUnstake {
                state: fixture.order_unstake_state,
                msol_mint: fixture.order_unstake_msol_mint,
                burn_msol_from: fixture.order_unstake_burn_msol_from,
                burn_msol_authority: payer.pubkey(),
                new_ticket_account: fixture.order_unstake_new_ticket_account,
                clock: crucible_fuzzer::anchor_lang::solana_program::sysvar::clock::ID,
                rent: crucible_fuzzer::anchor_lang::solana_program::sysvar::rent::ID,
                token_program: crucible_fuzzer::anchor_spl::token::ID,
            })
            .signers(&[&*payer])
            .send()
            .unwrap()
    }

    fn send_order_unstake_with_authority(
        fixture: &mut MarinadeFinanceFixture,
        authority: &Keypair,
        msol_amount: u64,
    ) -> crucible_test_context::TxOutcome {
        fixture
            .ctx
            .program(fixture.program_id)
            .call(instruction::OrderUnstake { msol_amount })
            .accounts(accounts::OrderUnstake {
                state: fixture.order_unstake_state,
                msol_mint: fixture.order_unstake_msol_mint,
                burn_msol_from: fixture.order_unstake_burn_msol_from,
                burn_msol_authority: authority.pubkey(),
                new_ticket_account: fixture.order_unstake_new_ticket_account,
                clock: crucible_fuzzer::anchor_lang::solana_program::sysvar::clock::ID,
                rent: crucible_fuzzer::anchor_lang::solana_program::sysvar::rent::ID,
                token_program: crucible_fuzzer::anchor_spl::token::ID,
            })
            .signers(&[authority])
            .send()
            .unwrap()
    }

    #[test]
    fn order_unstake_rejects_paused_state_guard() {
        let mut fixture = MarinadeFinanceFixture::setup();
        remint_order_unstake_state(&mut fixture, true, 1);
        let outcome = send_order_unstake_with_payer(&mut fixture, SCOUT_ORDER_UNSTAKE_MSOL_AMOUNT);
        assert!(!outcome.is_success());
    }

    #[test]
    fn order_unstake_rejects_min_withdraw_guard() {
        let mut fixture = MarinadeFinanceFixture::setup();
        remint_order_unstake_state(&mut fixture, false, SCOUT_ORDER_UNSTAKE_SOL_VALUE + 1);
        let outcome = send_order_unstake_with_payer(&mut fixture, SCOUT_ORDER_UNSTAKE_MSOL_AMOUNT);
        assert!(!outcome.is_success());
    }

    #[test]
    fn order_unstake_rejects_source_amount_guard() {
        let mut fixture = MarinadeFinanceFixture::setup();
        let outcome = send_order_unstake_with_payer(
            &mut fixture,
            SCOUT_ORDER_UNSTAKE_MINT_SUPPLY + 1,
        );
        assert!(!outcome.is_success());
    }

    #[test]
    fn order_unstake_rejects_wrong_owner_or_delegate_guard() {
        let mut fixture = MarinadeFinanceFixture::setup();
        let wrong_authority = Keypair::new();
        fund_system_signer(&mut fixture, &wrong_authority);
        let outcome = send_order_unstake_with_authority(
            &mut fixture,
            &wrong_authority,
            SCOUT_ORDER_UNSTAKE_MSOL_AMOUNT,
        );
        assert!(!outcome.is_success());
    }

    #[test]
    fn order_unstake_rejects_insufficient_delegated_amount_guard() {
        let mut fixture = MarinadeFinanceFixture::setup();
        let delegate = Keypair::new();
        fund_system_signer(&mut fixture, &delegate);
        remint_order_unstake_source(
            &mut fixture,
            Some(delegate.pubkey()),
            SCOUT_ORDER_UNSTAKE_MSOL_AMOUNT - 1,
            SCOUT_ORDER_UNSTAKE_MINT_SUPPLY,
        );
        let outcome = send_order_unstake_with_authority(
            &mut fixture,
            &delegate,
            SCOUT_ORDER_UNSTAKE_MSOL_AMOUNT,
        );
        assert!(!outcome.is_success());
    }
}

#[cfg(all(test, feature = "scout_orphaned_tests"))]
mod liquid_unstake_setup_glue_tests {
    use super::*;

    fn send_liquid_unstake_with_treasury(
        f: &mut MarinadeFinanceFixture,
        msol_amount: u64,
        treasury_msol_account: Pubkey,
    ) -> bool {
        f.ctx
            .program(f.program_id)
            .call(instruction::LiquidUnstake { msol_amount })
            .accounts(accounts::LiquidUnstake {
                state: f.state,
                msol_mint: f.msol_mint,
                liq_pool_sol_leg_pda: f.liq_pool_sol_leg_pda,
                liq_pool_msol_leg: f.liq_pool_msol_leg,
                treasury_msol_account,
                get_msol_from: f.mint_to,
                get_msol_from_authority: f.payer.pubkey(),
                transfer_sol_to: f.payer.pubkey(),
                system_program: system_program::ID,
                token_program: crucible_fuzzer::anchor_spl::token::ID,
            })
            .signers(&[&*f.payer])
            .send()
            .map(|outcome| outcome.is_success())
            .unwrap_or(false)
    }

    fn send_liquid_unstake(f: &mut MarinadeFinanceFixture, msol_amount: u64) -> bool {
        let treasury_msol_account = f.mint_to;
        send_liquid_unstake_with_treasury(f, msol_amount, treasury_msol_account)
    }

    fn rewrite_liquid_unstake_state(
        f: &mut MarinadeFinanceFixture,
        treasury_msol_account: Pubkey,
        paused: bool,
        min_withdraw: u64,
        total_virtual_lamports: u64,
        msol_supply: u64,
    ) {
        let state = scout_liquid_unstake_state(
            f.payer.pubkey(),
            f.program_id,
            f.state,
            f.msol_mint,
            f.liq_pool_msol_leg,
            treasury_msol_account,
            paused,
            min_withdraw,
            total_virtual_lamports,
            msol_supply,
        );
        let data = scout_state_data(&state);
        f.ctx.create_account()
            .pubkey(f.state)
            .owner(f.program_id)
            .data(&data)
            .create()
            .unwrap();
    }

    fn rewrite_user_msol_account(f: &mut MarinadeFinanceFixture, token_owner: Pubkey, amount: u64) {
        f.ctx.create_token_account()
            .pubkey(f.mint_to)
            .mint(f.msol_mint)
            .token_owner(token_owner)
            .amount(amount)
            .create()
            .unwrap();
    }

    fn rewrite_liq_pool_sol_leg(f: &mut MarinadeFinanceFixture, lamports: u64) {
        f.ctx.create_account()
            .pubkey(f.liq_pool_sol_leg_pda)
            .owner(system_program::ID)
            .lamports(lamports)
            .create()
            .unwrap();
    }

    #[test]
    fn liquid_unstake_reaches_process_from_fresh_setup() {
        let mut f = MarinadeFinanceFixture::setup();
        assert!(f.action_liquid_unstake());
    }

    #[test]
    fn liquid_unstake_succeeds_when_treasury_is_not_token_account() {
        let mut f = MarinadeFinanceFixture::setup();
        let payer_pubkey = f.payer.pubkey();
        rewrite_liquid_unstake_state(
            &mut f,
            payer_pubkey,
            false,
            1,
            SCOUT_LIQUID_UNSTAKE_TOTAL_LAMPORTS,
            SCOUT_LIQUID_UNSTAKE_MSOL_SUPPLY,
        );
        assert!(send_liquid_unstake_with_treasury(
            &mut f,
            SCOUT_LIQUID_UNSTAKE_MSOL_AMOUNT,
            payer_pubkey,
        ));
    }

    #[test]
    fn liquid_unstake_rejects_paused_state_guard() {
        let mut f = MarinadeFinanceFixture::setup();
        let treasury_msol_account = f.mint_to;
        rewrite_liquid_unstake_state(
            &mut f,
            treasury_msol_account,
            true,
            1,
            SCOUT_LIQUID_UNSTAKE_TOTAL_LAMPORTS,
            SCOUT_LIQUID_UNSTAKE_MSOL_SUPPLY,
        );
        assert!(!send_liquid_unstake(&mut f, SCOUT_LIQUID_UNSTAKE_MSOL_AMOUNT));
    }

    #[test]
    fn liquid_unstake_rejects_insufficient_user_msol_balance() {
        let mut f = MarinadeFinanceFixture::setup();
        let token_owner = f.payer.pubkey();
        rewrite_user_msol_account(
            &mut f,
            token_owner,
            SCOUT_LIQUID_UNSTAKE_MSOL_AMOUNT - 1,
        );
        assert!(!send_liquid_unstake(&mut f, SCOUT_LIQUID_UNSTAKE_MSOL_AMOUNT));
    }

    #[test]
    fn liquid_unstake_rejects_wrong_msol_owner() {
        let mut f = MarinadeFinanceFixture::setup();
        rewrite_user_msol_account(
            &mut f,
            Pubkey::new_unique(),
            SCOUT_LIQUID_UNSTAKE_MSOL_SUPPLY,
        );
        assert!(!send_liquid_unstake(&mut f, SCOUT_LIQUID_UNSTAKE_MSOL_AMOUNT));
    }

    #[test]
    fn liquid_unstake_rejects_insufficient_pool_sol() {
        let mut f = MarinadeFinanceFixture::setup();
        rewrite_liq_pool_sol_leg(&mut f, 1);
        assert!(!send_liquid_unstake(&mut f, SCOUT_LIQUID_UNSTAKE_MSOL_AMOUNT));
    }

    #[test]
    fn liquid_unstake_rejects_amount_below_min_withdraw() {
        let mut f = MarinadeFinanceFixture::setup();
        let treasury_msol_account = f.mint_to;
        rewrite_liquid_unstake_state(
            &mut f,
            treasury_msol_account,
            false,
            SCOUT_LIQUID_UNSTAKE_MSOL_AMOUNT + 1,
            SCOUT_LIQUID_UNSTAKE_TOTAL_LAMPORTS,
            SCOUT_LIQUID_UNSTAKE_MSOL_SUPPLY,
        );
        assert!(!send_liquid_unstake(&mut f, SCOUT_LIQUID_UNSTAKE_MSOL_AMOUNT));
    }
}

#[cfg(all(test, feature = "scout_orphaned_tests"))]
mod add_liquidity_setup_glue_tests {
    use super::*;

    fn send_add_liquidity(f: &mut MarinadeFinanceFixture, lamports: u64) -> bool {
        f.ctx
            .program(f.program_id)
            .call(instruction::AddLiquidity { lamports })
            .accounts(accounts::AddLiquidity {
                state: f.state,
                lp_mint: scout_add_liquidity_lp_mint(f.state, f.program_id),
                lp_mint_authority: Pubkey::find_program_address(
                    &[f.state.as_ref(), SCOUT_LP_MINT_AUTHORITY_SEED],
                    &f.program_id,
                )
                .0,
                liq_pool_msol_leg: f.liq_pool_msol_leg,
                liq_pool_sol_leg_pda: f.liq_pool_sol_leg_pda,
                transfer_from: f.payer.pubkey(),
                mint_to: scout_add_liquidity_mint_to(f.state, f.program_id),
                system_program: system_program::ID,
                token_program: crucible_fuzzer::anchor_spl::token::ID,
            })
            .signers(&[&*f.payer])
            .send()
            .map(|o| o.is_success())
            .unwrap_or(false)
    }

    fn rewrite_add_liquidity_state(
        f: &mut MarinadeFinanceFixture,
        edit: impl FnOnce(&mut marinade_finance::state::State),
    ) {
        let mut state = f
            .ctx
            .read_anchor_account::<marinade_finance::state::State>(&f.state)
            .unwrap();
        edit(&mut state);
        let data = scout_state_data(&state);
        f.ctx
            .create_account()
            .pubkey(f.state)
            .owner(f.program_id)
            .data(&data)
            .create()
            .unwrap();
    }

    #[test]
    fn add_liquidity_action_reaches_process_from_fresh_setup() {
        let mut f = MarinadeFinanceFixture::setup();
        assert!(f.action_add_liquidity());
    }

    #[test]
    fn add_liquidity_existing_lp_supply_uses_proportional_pricing() {
        let mut f = MarinadeFinanceFixture::setup();
        let lp_mint = scout_add_liquidity_lp_mint(f.state, f.program_id);
        let lp_mint_authority = Pubkey::find_program_address(
            &[f.state.as_ref(), SCOUT_LP_MINT_AUTHORITY_SEED],
            &f.program_id,
        )
        .0;
        f.ctx
            .create_mint()
            .pubkey(lp_mint)
            .mint_authority(lp_mint_authority)
            .supply(SCOUT_ADD_LIQUIDITY_LP_SUPPLY)
            .decimals(9)
            .freeze_authority(None)
            .create()
            .unwrap();
        f.ctx
            .create_account()
            .pubkey(f.liq_pool_sol_leg_pda)
            .owner(system_program::ID)
            .lamports(SCOUT_ADD_LIQUIDITY_LAMPORTS)
            .create()
            .unwrap();
        rewrite_add_liquidity_state(&mut f, |state| {
            state.liq_pool.lp_supply = SCOUT_ADD_LIQUIDITY_LP_SUPPLY;
        });
        assert!(send_add_liquidity(&mut f, SCOUT_ADD_LIQUIDITY_LAMPORTS));
    }

    #[test]
    fn add_liquidity_rejects_paused_state() {
        let mut f = MarinadeFinanceFixture::setup();
        rewrite_add_liquidity_state(&mut f, |state| {
            state.paused = true;
        });
        assert!(!send_add_liquidity(&mut f, SCOUT_ADD_LIQUIDITY_LAMPORTS));
    }

    #[test]
    fn add_liquidity_rejects_amount_below_min_deposit() {
        let mut f = MarinadeFinanceFixture::setup();
        assert!(!send_add_liquidity(&mut f, 0));
    }

    #[test]
    fn add_liquidity_rejects_insufficient_user_funds() {
        let mut f = MarinadeFinanceFixture::setup();
        assert!(!send_add_liquidity(&mut f, u64::MAX));
    }

    #[test]
    fn add_liquidity_rejects_liquidity_cap() {
        let mut f = MarinadeFinanceFixture::setup();
        rewrite_add_liquidity_state(&mut f, |state| {
            state.liq_pool.liquidity_sol_cap = 1;
        });
        assert!(!send_add_liquidity(&mut f, SCOUT_ADD_LIQUIDITY_LAMPORTS));
    }

    #[test]
    fn add_liquidity_rejects_unregistered_lp_mint_supply() {
        let mut f = MarinadeFinanceFixture::setup();
        let lp_mint = scout_add_liquidity_lp_mint(f.state, f.program_id);
        let lp_mint_authority = Pubkey::find_program_address(
            &[f.state.as_ref(), SCOUT_LP_MINT_AUTHORITY_SEED],
            &f.program_id,
        )
        .0;
        f.ctx
            .create_mint()
            .pubkey(lp_mint)
            .mint_authority(lp_mint_authority)
            .supply(1)
            .decimals(9)
            .freeze_authority(None)
            .create()
            .unwrap();
        assert!(!send_add_liquidity(&mut f, SCOUT_ADD_LIQUIDITY_LAMPORTS));
    }
}

