#[cfg(test)]
mod deactivate_stake_guard_tests {
    use super::*;

    fn send_deactivate_stake_direct(
        fixture: &mut MarinadeFinanceFixture,
    ) -> crucible_test_context::TxOutcome {
        let split_stake_account = Keypair::new();
        let payer = fixture.payer.clone();
        fixture
            .ctx
            .program(fixture.program_id)
            .call(instruction::DeactivateStake {
                stake_index: 0,
                validator_index: 0,
            })
            .accounts(accounts::DeactivateStake {
                state: fixture.state,
                reserve_pda: Pubkey::find_program_address(
                    &[fixture.state.as_ref(), SCOUT_RESERVE_SEED],
                    &fixture.program_id,
                )
                .0,
                validator_list: fixture.validator_list,
                stake_list: scout_deactivate_stake_list_key(fixture.state),
                stake_account: scout_deactivate_stake_account_key(fixture.state),
                stake_deposit_authority: Pubkey::find_program_address(
                    &[fixture.state.as_ref(), SCOUT_STAKE_DEPOSIT_SEED],
                    &fixture.program_id,
                )
                .0,
                split_stake_account: split_stake_account.pubkey(),
                split_stake_rent_payer: payer.pubkey(),
                clock: anchor_lang::solana_program::sysvar::clock::ID,
                rent: anchor_lang::solana_program::sysvar::rent::ID,
                epoch_schedule: anchor_lang::solana_program::sysvar::epoch_schedule::ID,
                stake_history: anchor_lang::solana_program::sysvar::stake_history::ID,
                system_program: system_program::ID,
                stake_program: anchor_lang::solana_program::stake::program::ID,
            })
            .signers(&[&*payer, &split_stake_account])
            .send()
            .unwrap()
    }

    fn prepare_deactivate_stake_guard_fixture(fixture: &mut MarinadeFinanceFixture) {
        scout_prepare_deactivate_stake_accounts(fixture);
        let mut state = fixture
            .ctx
            .read_anchor_account::<marinade_finance::state::State>(&fixture.state)
            .unwrap();
        state.stake_system.slots_for_stake_delta = u64::MAX;
        scout_rewrite_deactivate_state(fixture, state);
    }

    fn rewrite_deactivate_stake_list_record(
        fixture: &mut MarinadeFinanceFixture,
        delegated_lamports: u64,
        is_emergency_unstaking: bool,
        last_update_status: marinade_finance::types::StakeStatus,
    ) {
        let stake_account = scout_deactivate_stake_account_key(fixture.state);
        let clock = fixture.ctx.svm.get_sysvar::<anchor_lang::prelude::Clock>();
        let record = marinade_finance::types::StakeRecord {
            stake_account,
            last_update_delegated_lamports: delegated_lamports,
            last_update_epoch: clock.epoch,
            is_emergency_unstaking,
            last_update_status,
        };
        let mut record_data = Vec::new();
        record.serialize(&mut record_data).unwrap();
        let mut data = SCOUT_STAKE_LIST_DISCRIMINATOR.to_vec();
        data.extend_from_slice(&record_data);
        data.resize(8 + record_data.len() * SCOUT_STAKE_LIST_CAPACITY, 0);
        fixture
            .ctx
            .create_account()
            .pubkey(scout_deactivate_stake_list_key(fixture.state))
            .owner(fixture.program_id)
            .data(&data)
            .create()
            .unwrap();
    }

    fn rewrite_deactivate_native_stake(
        fixture: &mut MarinadeFinanceFixture,
        validator_vote: Pubkey,
        delegated_lamports: u64,
    ) {
        let stake_account = scout_deactivate_stake_account_key(fixture.state);
        let stake_deposit_authority = Pubkey::find_program_address(
            &[fixture.state.as_ref(), SCOUT_STAKE_DEPOSIT_SEED],
            &fixture.program_id,
        )
        .0;
        fixture
            .ctx
            .create_account()
            .pubkey(stake_account)
            .owner(solana_stake_interface::program::ID)
            .lamports(SCOUT_DEACTIVATE_STAKE_LAMPORTS)
            .data(&scout_deactivate_native_stake_account_data(
                stake_deposit_authority,
                validator_vote,
                delegated_lamports,
            ))
            .create()
            .unwrap();
    }

    fn rewrite_deactivate_initialized_stake(fixture: &mut MarinadeFinanceFixture) {
        let stake_account = scout_deactivate_stake_account_key(fixture.state);
        let stake_deposit_authority = Pubkey::find_program_address(
            &[fixture.state.as_ref(), SCOUT_STAKE_DEPOSIT_SEED],
            &fixture.program_id,
        )
        .0;
        fixture
            .ctx
            .create_account()
            .pubkey(stake_account)
            .owner(solana_stake_interface::program::ID)
            .lamports(SCOUT_DEACTIVATE_STAKE_LAMPORTS)
            .data(&scout_deposit_initialized_stake_account_data(
                stake_deposit_authority,
                0,
            ))
            .create()
            .unwrap();
    }

    #[test]
    fn deactivate_stake_rejects_delinquent_upgrader_guard() {
        let mut fixture = MarinadeFinanceFixture::setup();
        prepare_deactivate_stake_guard_fixture(&mut fixture);
        let mut state = fixture
            .ctx
            .read_anchor_account::<marinade_finance::state::State>(&fixture.state)
            .unwrap();
        state.delinquent_upgrader =
            marinade_finance::types::DelinquentUpgraderState::IteratingStakes {
                visited_count: 0,
                total_active_balance: 0,
                total_delinquent_balance: 0,
            };
        scout_rewrite_deactivate_state(&mut fixture, state);
        let outcome = send_deactivate_stake_direct(&mut fixture);
        assert!(!outcome.is_success());
    }

    #[test]
    fn deactivate_stake_rejects_non_active_stake_record_guard() {
        let mut fixture = MarinadeFinanceFixture::setup();
        prepare_deactivate_stake_guard_fixture(&mut fixture);
        rewrite_deactivate_stake_list_record(
            &mut fixture,
            SCOUT_DEACTIVATE_STAKE_LAMPORTS,
            false,
            marinade_finance::types::StakeStatus::Deactivating,
        );
        let outcome = send_deactivate_stake_direct(&mut fixture);
        assert!(!outcome.is_success());
    }

    #[test]
    fn deactivate_stake_rejects_emergency_unstaking_record_guard() {
        let mut fixture = MarinadeFinanceFixture::setup();
        prepare_deactivate_stake_guard_fixture(&mut fixture);
        rewrite_deactivate_stake_list_record(
            &mut fixture,
            SCOUT_DEACTIVATE_STAKE_LAMPORTS,
            true,
            marinade_finance::types::StakeStatus::Active,
        );
        let outcome = send_deactivate_stake_direct(&mut fixture);
        assert!(!outcome.is_success());
    }

    #[test]
    fn deactivate_stake_rejects_too_early_for_stake_delta_guard() {
        let mut fixture = MarinadeFinanceFixture::setup();
        scout_prepare_deactivate_stake_accounts(&mut fixture);
        let outcome = send_deactivate_stake_direct(&mut fixture);
        assert!(!outcome.is_success());
    }

    #[test]
    fn deactivate_stake_rejects_positive_delta_guard() {
        let mut fixture = MarinadeFinanceFixture::setup();
        prepare_deactivate_stake_guard_fixture(&mut fixture);
        let mut state = fixture
            .ctx
            .read_anchor_account::<marinade_finance::state::State>(&fixture.state)
            .unwrap();
        state.circulating_ticket_balance = 0;
        scout_rewrite_deactivate_state(&mut fixture, state);
        let outcome = send_deactivate_stake_direct(&mut fixture);
        assert!(!outcome.is_success());
    }

    #[test]
    fn deactivate_stake_rejects_wrong_validator_vote_guard() {
        let mut fixture = MarinadeFinanceFixture::setup();
        prepare_deactivate_stake_guard_fixture(&mut fixture);
        rewrite_deactivate_native_stake(
            &mut fixture,
            Pubkey::new_unique(),
            SCOUT_DEACTIVATE_STAKE_LAMPORTS,
        );
        let outcome = send_deactivate_stake_direct(&mut fixture);
        assert!(!outcome.is_success());
    }

    #[test]
    fn deactivate_stake_rejects_undelegated_stake_guard() {
        let mut fixture = MarinadeFinanceFixture::setup();
        prepare_deactivate_stake_guard_fixture(&mut fixture);
        rewrite_deactivate_initialized_stake(&mut fixture);
        let outcome = send_deactivate_stake_direct(&mut fixture);
        assert!(!outcome.is_success());
    }

    #[test]
    fn deactivate_stake_rejects_stale_stake_amount_guard() {
        let mut fixture = MarinadeFinanceFixture::setup();
        prepare_deactivate_stake_guard_fixture(&mut fixture);
        let validator_vote = scout_deactivate_validator_vote_key(fixture.state);
        rewrite_deactivate_native_stake(
            &mut fixture,
            validator_vote,
            SCOUT_DEACTIVATE_STAKE_LAMPORTS - 1,
        );
        let outcome = send_deactivate_stake_direct(&mut fixture);
        assert!(!outcome.is_success());
    }
}

