#[cfg(feature = "scout_orphaned_tests")]
#[cfg(test)]
mod stake_reserve_append_only_edge_tests {
    use super::*;

    fn rewrite_validator_record(
        fixture: &mut MarinadeFinanceFixture,
        record: marinade_finance::types::ValidatorRecord,
    ) {
        let mut validator_list_data = scout_validator_list_data(&[record]);
        validator_list_data.resize(
            8 + SCOUT_VALIDATOR_RECORD_SIZE * SCOUT_VALIDATOR_LIST_CAPACITY,
            0,
        );
        let mut account = fixture.ctx.read_account(&fixture.validator_list).unwrap();
        account.owner = fixture.program_id;
        account.data = validator_list_data;
        fixture.ctx.write_account(&fixture.validator_list, account).unwrap();
    }

    fn send_stake_reserve_with_index(
        fixture: &mut MarinadeFinanceFixture,
        validator_index: u32,
    ) -> crucible_test_context::TxOutcome {
        let stake_account = Keypair::new();
        let stake_list_pda = scout_stake_reserve_stake_list(&fixture.ctx, &fixture.state);
        fixture
            .ctx
            .program(fixture.program_id)
            .call(instruction::StakeReserve { validator_index })
            .accounts(accounts::StakeReserve {
                state: fixture.state,
                validator_list: fixture.validator_list,
                stake_list: stake_list_pda,
                validator_vote: fixture.validator_vote,
                reserve_pda: Pubkey::find_program_address(
                    &[fixture.state.as_ref(), SCOUT_RESERVE_SEED],
                    &fixture.program_id,
                )
                .0,
                stake_account: stake_account.pubkey(),
                stake_deposit_authority: Pubkey::find_program_address(
                    &[fixture.state.as_ref(), SCOUT_STAKE_DEPOSIT_SEED],
                    &fixture.program_id,
                )
                .0,
                rent_payer: fixture.payer.pubkey(),
                clock: crucible_fuzzer::anchor_lang::solana_program::sysvar::clock::ID,
                epoch_schedule: crucible_fuzzer::anchor_lang::solana_program::sysvar::epoch_schedule::ID,
                rent: crucible_fuzzer::anchor_lang::solana_program::sysvar::rent::ID,
                stake_history: crucible_fuzzer::anchor_lang::solana_program::sysvar::stake_history::ID,
                stake_config: crucible_fuzzer::anchor_lang::solana_program::stake::config::ID,
                system_program: system_program::ID,
                stake_program: crucible_fuzzer::anchor_lang::solana_program::stake::program::ID,
            })
            .signers(&[&*fixture.payer, &stake_account])
            .send()
            .unwrap()
    }

    // Calls `action_stake_reserve_signed`, a method never defined anywhere in this
    // harness (`grep -n "fn action_stake_reserve_signed" src/main.rs` returns nothing). Likely intended as a
    // bespoke variant of `action_stake_reserve`, but that variant was never implemented -- this predates
    // the compile-check gap fix, so it slipped in silently. Gated as orphaned rather than deleted
    // or guessed at: the exact intended semantics can't be safely reconstructed from the call site.
    #[cfg(feature = "scout_orphaned_tests")]
    #[test]
    fn stake_reserve_signed_wrapper_prepares_fresh_setup() {
        let mut fixture = MarinadeFinanceFixture::setup();
        assert!(fixture.action_stake_reserve_signed());
        let state = scout_read_marinade_state(&fixture.ctx, &fixture.state);
        assert_eq!(state.validator_system.total_active_balance, SCOUT_STAKE_RESERVE_STAKE_LAMPORTS);
    }

    #[test]
    fn stake_reserve_extra_delta_run_decrements_and_continues() {
        let mut fixture = MarinadeFinanceFixture::setup();
        scout_prepare_stake_reserve_positive_path(&mut fixture);
        let mut state = scout_read_marinade_state(&fixture.ctx, &fixture.state);
        state.stake_system.extra_stake_delta_runs = 1;
        scout_write_marinade_state(&mut fixture.ctx, fixture.state, &state);
        let mut record = scout_validator_record(
            fixture.state,
            fixture.validator_vote,
            fixture.program_id,
            SCOUT_STAKE_RESERVE_VALIDATOR_SCORE,
        )
        .0;
        record.last_stake_delta_epoch = 2;
        rewrite_validator_record(&mut fixture, record);
        assert!(fixture.action_stake_reserve());
        let state = scout_read_marinade_state(&fixture.ctx, &fixture.state);
        assert_eq!(state.stake_system.extra_stake_delta_runs, 0);
        assert_eq!(state.validator_system.total_active_balance, SCOUT_STAKE_RESERVE_STAKE_LAMPORTS);
    }

    #[test]
    fn stake_reserve_stakes_partial_validator_target_when_remainder_is_large() {
        let mut fixture = MarinadeFinanceFixture::setup();
        scout_prepare_stake_reserve_positive_path(&mut fixture);
        let mut state = scout_read_marinade_state(&fixture.ctx, &fixture.state);
        state.validator_system.total_validator_score = SCOUT_STAKE_RESERVE_VALIDATOR_SCORE * 2;
        scout_write_marinade_state(&mut fixture.ctx, fixture.state, &state);
        assert!(fixture.action_stake_reserve());
        let state = scout_read_marinade_state(&fixture.ctx, &fixture.state);
        assert_eq!(state.validator_system.total_active_balance, SCOUT_STAKE_RESERVE_STAKE_LAMPORTS / 2);
        assert_eq!(state.available_reserve_balance, SCOUT_STAKE_RESERVE_STAKE_LAMPORTS / 2);
    }

    #[test]
    fn stake_reserve_rejects_bad_validator_index() {
        let mut fixture = MarinadeFinanceFixture::setup();
        scout_prepare_stake_reserve_positive_path(&mut fixture);
        let outcome = send_stake_reserve_with_index(&mut fixture, 1);
        assert!(!outcome.is_success());
    }
}

