#[cfg(test)]
mod liquid_unstake_v4_source_guard_tests {
    use super::*;

    fn fund_liquid_unstake_v4_signer(f: &mut MarinadeFinanceFixture, signer: &Keypair) {
        f.ctx
            .create_account()
            .pubkey(signer.pubkey())
            .lamports(1_000_000_000)
            .owner(system_program::ID)
            .create()
            .unwrap();
    }

    fn remint_liquid_unstake_v4_user_token(
        f: &mut MarinadeFinanceFixture,
        delegate: Option<Pubkey>,
        delegated_amount: u64,
        amount: u64,
    ) {
        f.ctx
            .create_token_account()
            .pubkey(scout_liquid_unstake_v4_user_msol_pubkey(f.program_id))
            .mint(scout_liquid_unstake_v4_msol_mint_pubkey(f.program_id))
            .token_owner(f.payer.pubkey())
            .delegate(delegate)
            .delegated_amount(delegated_amount)
            .amount(amount)
            .create()
            .unwrap();
    }

    fn send_liquid_unstake_v4_with_authority(
        f: &mut MarinadeFinanceFixture,
        authority: &Keypair,
        msol_amount: u64,
        treasury_msol_account: Pubkey,
    ) -> bool {
        f.ctx
            .program(f.program_id)
            .call(instruction::LiquidUnstake { msol_amount })
            .accounts(accounts::LiquidUnstake {
                state: scout_liquid_unstake_v4_state_pubkey(f.program_id),
                msol_mint: scout_liquid_unstake_v4_msol_mint_pubkey(f.program_id),
                liq_pool_sol_leg_pda: scout_liquid_unstake_v4_sol_leg_pubkey(f.program_id),
                liq_pool_msol_leg: scout_liquid_unstake_v4_pool_msol_pubkey(f.program_id),
                treasury_msol_account,
                get_msol_from: scout_liquid_unstake_v4_user_msol_pubkey(f.program_id),
                get_msol_from_authority: authority.pubkey(),
                transfer_sol_to: f.payer.pubkey(),
                system_program: system_program::ID,
                token_program: crucible_fuzzer::anchor_spl::token::ID,
            })
            .signers(&[authority])
            .send()
            .map(|outcome| outcome.is_success())
            .unwrap_or(false)
    }

    #[test]
    fn liquid_unstake_v4_rejects_wrong_owner_or_delegate_guard() {
        let mut f = MarinadeFinanceFixture::setup();
        let wrong_authority = Keypair::new();
        fund_liquid_unstake_v4_signer(&mut f, &wrong_authority);
        let treasury_msol_account = scout_liquid_unstake_v4_treasury_msol_pubkey(f.program_id);
        scout_prepare_liquid_unstake_v4_accounts(
            &mut f,
            treasury_msol_account,
            true,
            SCOUT_LIQUID_UNSTAKE_POOL_SOL,
            SCOUT_LIQUID_UNSTAKE_MSOL_SUPPLY,
            1,
            false,
        );
        assert!(!send_liquid_unstake_v4_with_authority(
            &mut f,
            &wrong_authority,
            SCOUT_LIQUID_UNSTAKE_MSOL_AMOUNT,
            treasury_msol_account,
        ));
    }

    #[test]
    fn liquid_unstake_v4_rejects_insufficient_delegated_amount_guard() {
        let mut f = MarinadeFinanceFixture::setup();
        let delegate = Keypair::new();
        fund_liquid_unstake_v4_signer(&mut f, &delegate);
        let treasury_msol_account = scout_liquid_unstake_v4_treasury_msol_pubkey(f.program_id);
        scout_prepare_liquid_unstake_v4_accounts(
            &mut f,
            treasury_msol_account,
            true,
            SCOUT_LIQUID_UNSTAKE_POOL_SOL,
            SCOUT_LIQUID_UNSTAKE_MSOL_SUPPLY,
            1,
            false,
        );
        remint_liquid_unstake_v4_user_token(
            &mut f,
            Some(delegate.pubkey()),
            SCOUT_LIQUID_UNSTAKE_MSOL_AMOUNT - 1,
            SCOUT_LIQUID_UNSTAKE_MSOL_SUPPLY,
        );
        assert!(!send_liquid_unstake_v4_with_authority(
            &mut f,
            &delegate,
            SCOUT_LIQUID_UNSTAKE_MSOL_AMOUNT,
            treasury_msol_account,
        ));
    }
}

