#[cfg(all(test, feature = "scout_orphaned_tests"))]
mod finalize_delinquent_upgrade_setup_glue_tests {
    use super::*;

    fn send_finalize_delinquent_upgrade(
        fixture: &mut MarinadeFinanceFixture,
        max_validators: u32,
    ) -> crucible_test_context::TxOutcome {
        fixture
            .ctx
            .program(fixture.program_id)
            .call(instruction::FinalizeDelinquentUpgrade { max_validators })
            .accounts(accounts::FinalizeDelinquentUpgrade {
                state: fixture.state,
                validator_list: fixture.validator_list,
            })
            .signers(&[&*fixture.payer])
            .send()
            .unwrap()
    }

    #[test]
    fn finalize_delinquent_upgrade_generated_action_reaches_success_path() {
        let mut fixture = MarinadeFinanceFixture::setup();
        assert!(fixture.action_finalize_delinquent_upgrade());
        let state = scout_read_marinade_state(&fixture.ctx, &fixture.state);
        assert!(matches!(
            state.delinquent_upgrader,
            marinade_finance::types::DelinquentUpgraderState::Done
        ));
        let validator_list_account = fixture.ctx.read_account(&fixture.validator_list).unwrap();
        let validator =
            <marinade_finance::types::ValidatorRecord as ::anchor_lang::AnchorDeserialize>::deserialize(
                &mut &validator_list_account.data[8..],
            )
            .unwrap();
        assert_eq!(validator.active_balance, 0);
        assert_eq!(validator.delinquent_upgrader_active_balance, 0);
    }

    #[test]
    fn finalize_delinquent_upgrade_zero_max_keeps_partial_progress_state() {
        let mut fixture = MarinadeFinanceFixture::setup();
        scout_prepare_finalize_delinquent_upgrade_action(&mut fixture);
        let outcome = send_finalize_delinquent_upgrade(&mut fixture, 0);
        assert!(outcome.is_success(), "zero-max finalize failed: {:?}", outcome);
        let state = scout_read_marinade_state(&fixture.ctx, &fixture.state);
        match state.delinquent_upgrader {
            marinade_finance::types::DelinquentUpgraderState::IteratingValidators {
                visited_count,
                delinquent_balance_left,
            } => {
                assert_eq!(visited_count, 0);
                assert_eq!(delinquent_balance_left, 0);
            }
            // `DelinquentUpgraderState` has no `Debug` impl (it's IDL-generated, not hand-written
            // in this harness), so the mismatch is described by variant name instead of `{:?}`.
            marinade_finance::types::DelinquentUpgraderState::Done => {
                panic!("expected partial validator iteration, got Done")
            }
            marinade_finance::types::DelinquentUpgraderState::IteratingStakes { .. } => {
                panic!("expected partial validator iteration, got IteratingStakes")
            }
        }
    }

    #[test]
    fn finalize_delinquent_upgrade_rejects_paused_state_guard() {
        let mut fixture = MarinadeFinanceFixture::setup();
        scout_prepare_finalize_delinquent_upgrade_with_state(
            &mut fixture,
            true,
            marinade_finance::types::DelinquentUpgraderState::IteratingValidators {
                visited_count: 0,
                delinquent_balance_left: 0,
            },
            0,
            0,
        );
        let outcome = send_finalize_delinquent_upgrade(&mut fixture, 1);
        assert!(!outcome.is_success(), "paused finalize unexpectedly succeeded");
        assert!(
            outcome
                .logs()
                .iter()
                .any(|line| line.contains("ProgramIsPaused")),
            "paused finalize should fail ProgramIsPaused: {:?}",
            outcome
        );
    }

    #[test]
    fn finalize_delinquent_upgrade_rejects_wrong_upgrader_state() {
        let mut fixture = MarinadeFinanceFixture::setup();
        scout_prepare_finalize_delinquent_upgrade_with_state(
            &mut fixture,
            false,
            marinade_finance::types::DelinquentUpgraderState::Done,
            0,
            0,
        );
        let outcome = send_finalize_delinquent_upgrade(&mut fixture, 1);
        assert!(
            !outcome.is_success(),
            "wrong-state finalize unexpectedly succeeded"
        );
        assert!(
            outcome
                .logs()
                .iter()
                .any(|line| line.contains("UpgradingInvariantViolation")),
            "wrong-state finalize should fail UpgradingInvariantViolation: {:?}",
            outcome
        );
    }

    #[test]
    fn finalize_delinquent_upgrade_rejects_nonzero_balance_left_invariant() {
        let mut fixture = MarinadeFinanceFixture::setup();
        scout_prepare_finalize_delinquent_upgrade_with_state(
            &mut fixture,
            false,
            marinade_finance::types::DelinquentUpgraderState::IteratingValidators {
                visited_count: 0,
                delinquent_balance_left: 1,
            },
            0,
            0,
        );
        let outcome = send_finalize_delinquent_upgrade(&mut fixture, 1);
        assert!(
            !outcome.is_success(),
            "nonzero balance-left finalize unexpectedly succeeded"
        );
        assert!(
            outcome
                .logs()
                .iter()
                .any(|line| line.contains("UpgradingInvariantViolation")),
            "nonzero balance-left finalize should fail UpgradingInvariantViolation: {:?}",
            outcome
        );
    }
}

