#[cfg(test)]
mod deposit_context_guard_append_tests {
    use super::*;

    fn send_deposit_with_remaining_account(fixture: &mut MarinadeFinanceFixture) -> bool {
        let extra_account = Pubkey::new_unique();
        fixture
            .ctx
            .create_account()
            .pubkey(extra_account)
            .owner(system_program::ID)
            .create()
            .unwrap();
        fixture
            .ctx
            .program(fixture.program_id)
            .call(instruction::Deposit { lamports: 600_000_000 })
            .accounts(accounts::Deposit {
                state: fixture.state,
                msol_mint: fixture.msol_mint,
                liq_pool_sol_leg_pda: fixture.liq_pool_sol_leg_pda,
                liq_pool_msol_leg: fixture.liq_pool_msol_leg,
                liq_pool_msol_leg_authority: fixture.liq_pool_msol_leg_authority,
                reserve_pda: fixture.reserve_pda,
                transfer_from: fixture.payer.pubkey(),
                mint_to: fixture.mint_to,
                msol_mint_authority: fixture.msol_mint_authority,
                system_program: system_program::ID,
                token_program: crucible_fuzzer::anchor_spl::token::ID,
            })
            .remaining_accounts(vec![extra_account])
            .signers(&[&*fixture.payer])
            .send()
            .map(|outcome| outcome.is_success())
            .unwrap_or(false)
    }

    fn send_deposit_through_wrong_program_id() -> bool {
        let mut ctx = crate::__scout_crucible_test_context::TestContext::new();
        let declared_program_id = Pubkey::new_from_array(marinade_finance::ID.to_bytes());
        let wrong_program_id = Pubkey::new_unique();
        crate::__scout_crucible_test_context::TestContext::add_program(
            &mut ctx,
            &wrong_program_id,
            SCOUT_TARGET_PROGRAM_ARTIFACT,
        )
        .unwrap();
        let payer = Rc::new(Keypair::new());
        ctx.create_account()
            .pubkey(payer.pubkey())
            .lamports(1_000_000_000)
            .owner(system_program::ID)
            .create()
            .unwrap();

        let state = Pubkey::new_unique();
        let msol_mint = Pubkey::new_unique();
        let liq_pool_msol_leg = Pubkey::new_unique();
        let mint_to = Pubkey::new_unique();
        let (liq_pool_sol_leg_pda, _) = Pubkey::find_program_address(
            &[state.as_ref(), SCOUT_LIQ_POOL_SOL_LEG_SEED],
            &wrong_program_id,
        );
        let (liq_pool_msol_leg_authority, _) = Pubkey::find_program_address(
            &[state.as_ref(), SCOUT_LIQ_POOL_MSOL_LEG_AUTHORITY_SEED],
            &wrong_program_id,
        );
        let (reserve_pda, _) =
            Pubkey::find_program_address(&[state.as_ref(), SCOUT_RESERVE_SEED], &wrong_program_id);
        let (msol_mint_authority, _) = Pubkey::find_program_address(
            &[state.as_ref(), SCOUT_MSOL_MINT_AUTHORITY_SEED],
            &wrong_program_id,
        );

        ctx.create_mint()
            .pubkey(msol_mint)
            .mint_authority(msol_mint_authority)
            .decimals(9)
            .freeze_authority(None)
            .create()
            .unwrap();
        ctx.create_token_account()
            .pubkey(liq_pool_msol_leg)
            .mint(msol_mint)
            .token_owner(liq_pool_msol_leg_authority)
            .amount(SCOUT_DEPOSIT_LIQ_POOL_MSOL_BALANCE)
            .create()
            .unwrap();
        ctx.create_token_account()
            .pubkey(mint_to)
            .mint(msol_mint)
            .token_owner(payer.pubkey())
            .create()
            .unwrap();
        ctx.create_account()
            .pubkey(liq_pool_sol_leg_pda)
            .owner(system_program::ID)
            .create()
            .unwrap();
        ctx.create_account()
            .pubkey(reserve_pda)
            .owner(system_program::ID)
            .create()
            .unwrap();
        let state_value = scout_deposit_state(
            payer.pubkey(),
            wrong_program_id,
            state,
            msol_mint,
            liq_pool_msol_leg,
            false,
            u64::MAX,
            0,
        );
        ctx.create_account()
            .pubkey(state)
            .owner(declared_program_id)
            .data(&scout_state_data(&state_value))
            .create()
            .unwrap();

        ctx.program(wrong_program_id)
            .call(instruction::Deposit { lamports: 600_000_000 })
            .accounts(accounts::Deposit {
                state,
                msol_mint,
                liq_pool_sol_leg_pda,
                liq_pool_msol_leg,
                liq_pool_msol_leg_authority,
                reserve_pda,
                transfer_from: payer.pubkey(),
                mint_to,
                msol_mint_authority,
                system_program: system_program::ID,
                token_program: crucible_fuzzer::anchor_spl::token::ID,
            })
            .signers(&[&*payer])
            .send()
            .map(|outcome| outcome.is_success())
            .unwrap_or(false)
    }

    #[test]
    fn deposit_rejects_unexpected_remaining_account() {
        let mut fixture = MarinadeFinanceFixture::setup();
        assert!(!send_deposit_with_remaining_account(&mut fixture));
    }

    #[test]
    fn deposit_rejects_wrong_program_id_context() {
        assert!(!send_deposit_through_wrong_program_id());
    }
}

