#[cfg(test)]
mod remove_liquidity_invalid_program_id_append_tests {
    use super::*;

    #[test]
    fn remove_liquidity_rejects_invalid_program_id_context_guard() {
        let mut ctx = crate::__scout_crucible_test_context::TestContext::new();
        let declared_program_id = Pubkey::new_from_array(marinade_finance::ID.to_bytes());
        let wrong_program_id = Pubkey::new_unique();
        crate::__scout_crucible_test_context::TestContext::add_program(
            &mut ctx,
            &wrong_program_id,
            SCOUT_TARGET_PROGRAM_ARTIFACT,
        )
        .unwrap();
        let payer = Rc::new(Keypair::new());
        ctx.create_account()
            .pubkey(payer.pubkey())
            .lamports(1_000_000_000)
            .owner(system_program::ID)
            .create()
            .unwrap();

        let state = Pubkey::new_unique();
        let validator_list = Pubkey::new_unique();
        let msol_mint = Pubkey::new_unique();
        let liq_pool_msol_leg = Pubkey::new_unique();
        let lp_mint = scout_remove_liquidity_lp_mint(state, wrong_program_id);
        let burn_from = scout_remove_liquidity_burn_from(state, wrong_program_id);
        let transfer_msol_to = scout_remove_liquidity_transfer_msol_to(state, wrong_program_id);
        let liq_pool_sol_leg_pda = Pubkey::find_program_address(
            &[state.as_ref(), SCOUT_LIQ_POOL_SOL_LEG_SEED],
            &wrong_program_id,
        )
        .0;
        let liq_pool_msol_leg_authority = Pubkey::find_program_address(
            &[state.as_ref(), SCOUT_LIQ_POOL_MSOL_LEG_AUTHORITY_SEED],
            &wrong_program_id,
        )
        .0;
        let state_value = scout_remove_liquidity_state(
            payer.pubkey(),
            wrong_program_id,
            state,
            validator_list,
            msol_mint,
            liq_pool_msol_leg,
            SCOUT_REMOVE_LIQUIDITY_LP_SUPPLY,
            false,
            1,
        );
        ctx.create_account()
            .pubkey(state)
            .owner(declared_program_id)
            .data(&scout_state_data(&state_value))
            .create()
            .unwrap();
        ctx.create_mint()
            .pubkey(msol_mint)
            .mint_authority(payer.pubkey())
            .supply(SCOUT_REMOVE_LIQUIDITY_MSOL_SUPPLY)
            .decimals(9)
            .freeze_authority(None)
            .create()
            .unwrap();
        ctx.create_mint()
            .pubkey(lp_mint)
            .mint_authority(payer.pubkey())
            .supply(SCOUT_REMOVE_LIQUIDITY_LP_SUPPLY)
            .decimals(9)
            .freeze_authority(None)
            .create()
            .unwrap();
        ctx.create_token_account()
            .pubkey(burn_from)
            .mint(lp_mint)
            .token_owner(payer.pubkey())
            .amount(SCOUT_REMOVE_LIQUIDITY_LP_SUPPLY)
            .create()
            .unwrap();
        ctx.create_token_account()
            .pubkey(transfer_msol_to)
            .mint(msol_mint)
            .token_owner(payer.pubkey())
            .create()
            .unwrap();
        ctx.create_token_account()
            .pubkey(liq_pool_msol_leg)
            .mint(msol_mint)
            .token_owner(liq_pool_msol_leg_authority)
            .amount(SCOUT_REMOVE_LIQUIDITY_MSOL_LEG_AMOUNT)
            .create()
            .unwrap();
        ctx.create_account()
            .pubkey(liq_pool_sol_leg_pda)
            .owner(system_program::ID)
            .lamports(SCOUT_REMOVE_LIQUIDITY_SOL_LEG_LAMPORTS)
            .create()
            .unwrap();

        let outcome = ctx
            .program(wrong_program_id)
            .call(instruction::RemoveLiquidity {
                tokens: SCOUT_REMOVE_LIQUIDITY_TOKENS,
            })
            .accounts(accounts::RemoveLiquidity {
                state,
                lp_mint,
                burn_from,
                burn_from_authority: payer.pubkey(),
                transfer_sol_to: payer.pubkey(),
                transfer_msol_to,
                liq_pool_sol_leg_pda,
                liq_pool_msol_leg,
                liq_pool_msol_leg_authority,
                system_program: system_program::ID,
                token_program: crucible_fuzzer::anchor_spl::token::ID,
            })
            .signers(&[&*payer])
            .send()
            .unwrap();
        assert!(!outcome.is_success());
    }
}

