#[cfg(test)]
mod merge_stakes_context_guard_append_tests {
    use super::*;

    fn send_merge_stakes_context_guard(
        ctx: &mut crate::__scout_crucible_test_context::TestContext,
        program_id: Pubkey,
        payer: &Rc<Keypair>,
        state: Pubkey,
        remaining_accounts: Vec<Pubkey>,
    ) -> crucible_test_context::TxOutcome {
        ctx.program(program_id)
            .call(instruction::MergeStakes {
                destination_stake_index: 0,
                source_stake_index: 1,
                validator_index: 0,
            })
            .accounts(accounts::MergeStakes {
                state,
                stake_list: scout_merge_stake_list_pubkey(),
                validator_list: scout_merge_validator_list_pubkey(),
                destination_stake: scout_merge_destination_stake_pubkey(&program_id),
                source_stake: scout_merge_source_stake_pubkey(),
                stake_deposit_authority: Pubkey::find_program_address(
                    &[state.as_ref(), SCOUT_STAKE_DEPOSIT_SEED],
                    &program_id,
                )
                .0,
                stake_withdraw_authority: Pubkey::find_program_address(
                    &[state.as_ref(), SCOUT_STAKE_WITHDRAW_SEED],
                    &program_id,
                )
                .0,
                operational_sol_account: scout_merge_operational_sol_account_pubkey(),
                clock: crucible_fuzzer::anchor_lang::solana_program::sysvar::clock::ID,
                stake_history: crucible_fuzzer::anchor_lang::solana_program::sysvar::stake_history::ID,
                stake_program: solana_stake_interface::program::ID,
            })
            .remaining_accounts(remaining_accounts)
            .signers(&[&**payer])
            .send()
            .unwrap()
    }

    fn mint_merge_stakes_context_accounts(
        ctx: &mut crate::__scout_crucible_test_context::TestContext,
        owner_program_id: Pubkey,
        pda_program_id: Pubkey,
        payer: Pubkey,
        state: Pubkey,
    ) {
        let validator_vote = scout_merge_validator_vote_pubkey();
        let destination_stake = scout_merge_destination_stake_pubkey(&pda_program_id);
        let source_stake = scout_merge_source_stake_pubkey();
        let stake_deposit_authority = Pubkey::find_program_address(
            &[state.as_ref(), SCOUT_STAKE_DEPOSIT_SEED],
            &pda_program_id,
        )
        .0;
        let stake_withdraw_authority = Pubkey::find_program_address(
            &[state.as_ref(), SCOUT_STAKE_WITHDRAW_SEED],
            &pda_program_id,
        )
        .0;
        let state_account = scout_merge_state_account(
            payer,
            pda_program_id,
            state,
            scout_merge_stake_list_pubkey(),
            scout_merge_validator_list_pubkey(),
            scout_merge_operational_sol_account_pubkey(),
        );
        ctx.create_account()
            .pubkey(state)
            .owner(owner_program_id)
            .data(&scout_state_data(&state_account))
            .create()
            .unwrap();
        ctx.create_account()
            .pubkey(scout_merge_stake_list_pubkey())
            .owner(owner_program_id)
            .data(&scout_merge_stake_list_data(destination_stake, source_stake))
            .create()
            .unwrap();
        ctx.create_account()
            .pubkey(scout_merge_validator_list_pubkey())
            .owner(owner_program_id)
            .data(&scout_merge_validator_list_data(state, validator_vote, pda_program_id))
            .create()
            .unwrap();
        ctx.create_account()
            .pubkey(destination_stake)
            .owner(solana_stake_interface::program::ID)
            .lamports(SCOUT_MERGE_DESTINATION_STAKE_LAMPORTS + SCOUT_MERGE_STAKE_RENT_LAMPORTS)
            .data(&scout_deposit_stake_account_data(
                stake_deposit_authority,
                stake_withdraw_authority,
                validator_vote,
                SCOUT_MERGE_DESTINATION_STAKE_LAMPORTS,
                SCOUT_MERGE_STAKE_RENT_LAMPORTS,
                0,
                u64::MAX,
                solana_stake_interface::state::Lockup::default(),
            ))
            .create()
            .unwrap();
        ctx.create_account()
            .pubkey(source_stake)
            .owner(solana_stake_interface::program::ID)
            .lamports(SCOUT_MERGE_SOURCE_STAKE_LAMPORTS + SCOUT_MERGE_STAKE_RENT_LAMPORTS)
            .data(&scout_deposit_stake_account_data(
                stake_deposit_authority,
                stake_withdraw_authority,
                validator_vote,
                SCOUT_MERGE_SOURCE_STAKE_LAMPORTS,
                SCOUT_MERGE_STAKE_RENT_LAMPORTS,
                0,
                u64::MAX,
                solana_stake_interface::state::Lockup::default(),
            ))
            .create()
            .unwrap();
        ctx.create_account()
            .pubkey(scout_merge_operational_sol_account_pubkey())
            .owner(system_program::ID)
            .lamports(1_000_000)
            .create()
            .unwrap();
        ctx.set_sysvar(&scout_claim_clock(2, 3_600));
    }

    #[test]
    fn merge_stakes_rejects_unexpected_remaining_account() {
        let mut fixture = MarinadeFinanceFixture::setup();
        scout_prepare_merge_stakes_active_rent(&mut fixture);
        let extra_account = Pubkey::new_unique();
        fixture.ctx
            .create_account()
            .pubkey(extra_account)
            .owner(system_program::ID)
            .create()
            .unwrap();
        let state = scout_merge_state_pubkey();
        let outcome = send_merge_stakes_context_guard(
            &mut fixture.ctx,
            fixture.program_id,
            &fixture.payer,
            state,
            vec![extra_account],
        );
        assert!(!outcome.is_success());
    }

    #[test]
    fn merge_stakes_rejects_invalid_program_id_context_guard() {
        let mut ctx = crate::__scout_crucible_test_context::TestContext::new();
        let declared_program_id = Pubkey::new_from_array(marinade_finance::ID.to_bytes());
        let wrong_program_id = Pubkey::new_unique();
        crate::__scout_crucible_test_context::TestContext::add_program(
            &mut ctx,
            &wrong_program_id,
            SCOUT_TARGET_PROGRAM_ARTIFACT,
        )
        .unwrap();
        let payer = Rc::new(Keypair::new());
        ctx.create_account()
            .pubkey(payer.pubkey())
            .lamports(1_000_000_000)
            .owner(system_program::ID)
            .create()
            .unwrap();
        let state = scout_merge_state_pubkey();
        mint_merge_stakes_context_accounts(
            &mut ctx,
            declared_program_id,
            wrong_program_id,
            payer.pubkey(),
            state,
        );
        let outcome = send_merge_stakes_context_guard(
            &mut ctx,
            wrong_program_id,
            &payer,
            state,
            Vec::new(),
        );
        assert!(!outcome.is_success());
    }
}

