#[cfg(test)]
mod remove_liquidity_native_cpi_wall_tests {
    use super::*;

    // Builds a fully self-contained remove_liquidity fixture (own state/mints/legs, independent
    // of the shared default fixture) so `sol_leg_lamports`/`msol_leg_amount`/`lp_supply` can be
    // chosen precisely to steer `sol_out_amount`/`msol_out_amount` (remove_liquidity.rs:92-101,
    // both computed via `proportional(tokens, leg_balance, lp_supply)` -- integer division,
    // rounds down to 0 when `tokens * leg_balance < lp_supply`) into each of the three CPI-branch
    // combinations the handler can take.
    fn send_remove_liquidity_custom(
        f: &mut MarinadeFinanceFixture,
        tokens: u64,
        sol_leg_lamports: u64,
        msol_leg_amount: u64,
        lp_supply: u64,
        min_withdraw: u64,
    ) -> Vec<String> {
        send_remove_liquidity_custom_with_mint_supply(
            f,
            tokens,
            sol_leg_lamports,
            msol_leg_amount,
            lp_supply,
            lp_supply,
            min_withdraw,
        )
    }

    // Like `send_remove_liquidity_custom`, but lets the REAL `lp_mint.supply` diverge from
    // `state.liq_pool.lp_supply` -- needed to independently drive remove_liquidity.rs:83's
    // `lp_mint_supply > self.state.liq_pool.lp_supply` branch either way (the two are conflated
    // in the simpler helper above, which always keeps them equal and so only ever exercises the
    // FALSE/`else` branch at :86-89).
    fn send_remove_liquidity_custom_with_mint_supply(
        f: &mut MarinadeFinanceFixture,
        tokens: u64,
        sol_leg_lamports: u64,
        msol_leg_amount: u64,
        lp_supply: u64,
        lp_mint_supply: u64,
        min_withdraw: u64,
    ) -> Vec<String> {
        let (liq_pool_sol_leg_pda, _) =
            Pubkey::find_program_address(&[f.state.as_ref(), SCOUT_LIQ_POOL_SOL_LEG_SEED], &f.program_id);
        let (liq_pool_msol_leg_authority, _) = Pubkey::find_program_address(
            &[f.state.as_ref(), SCOUT_LIQ_POOL_MSOL_LEG_AUTHORITY_SEED],
            &f.program_id,
        );
        let (msol_mint_authority, _) =
            Pubkey::find_program_address(&[f.state.as_ref(), SCOUT_MSOL_MINT_AUTHORITY_SEED], &f.program_id);
        f.liq_pool_sol_leg_pda = liq_pool_sol_leg_pda;
        f.liq_pool_msol_leg_authority = liq_pool_msol_leg_authority;
        f.msol_mint_authority = msol_mint_authority;

        let lp_mint = scout_remove_liquidity_lp_mint(f.state, f.program_id);
        let burn_from = scout_remove_liquidity_burn_from(f.state, f.program_id);
        let transfer_msol_to = scout_remove_liquidity_transfer_msol_to(f.state, f.program_id);
        let state = scout_remove_liquidity_state(
            f.payer.pubkey(),
            f.program_id,
            f.state,
            f.validator_list,
            f.msol_mint,
            f.liq_pool_msol_leg,
            lp_supply,
            false,
            min_withdraw,
        );
        f.ctx
            .create_account()
            .pubkey(f.state)
            .owner(f.program_id)
            .data(&scout_state_data(&state))
            .create()
            .unwrap();
        f.ctx
            .create_mint()
            .pubkey(f.msol_mint)
            .mint_authority(msol_mint_authority)
            .supply(SCOUT_REMOVE_LIQUIDITY_MSOL_SUPPLY)
            .decimals(9)
            .freeze_authority(None)
            .create()
            .unwrap();
        f.ctx
            .create_mint()
            .pubkey(lp_mint)
            .mint_authority(f.payer.pubkey())
            .supply(lp_mint_supply)
            .decimals(9)
            .freeze_authority(None)
            .create()
            .unwrap();
        f.ctx
            .create_token_account()
            .pubkey(burn_from)
            .mint(lp_mint)
            .token_owner(f.payer.pubkey())
            .amount(lp_mint_supply)
            .create()
            .unwrap();
        f.ctx
            .create_token_account()
            .pubkey(transfer_msol_to)
            .mint(f.msol_mint)
            .token_owner(f.payer.pubkey())
            .amount(0)
            .create()
            .unwrap();
        f.ctx
            .create_token_account()
            .pubkey(f.liq_pool_msol_leg)
            .mint(f.msol_mint)
            .token_owner(liq_pool_msol_leg_authority)
            .amount(msol_leg_amount)
            .create()
            .unwrap();
        f.ctx
            .create_account()
            .pubkey(liq_pool_sol_leg_pda)
            .owner(system_program::ID)
            .lamports(sol_leg_lamports)
            .create()
            .unwrap();

        let outcome = f
            .ctx
            .program(f.program_id)
            .call(instruction::RemoveLiquidity { tokens })
            .accounts(accounts::RemoveLiquidity {
                state: f.state,
                lp_mint,
                burn_from,
                burn_from_authority: f.payer.pubkey(),
                transfer_sol_to: f.payer.pubkey(),
                transfer_msol_to,
                liq_pool_sol_leg_pda,
                liq_pool_msol_leg: f.liq_pool_msol_leg,
                liq_pool_msol_leg_authority,
                system_program: system_program::ID,
                token_program: crucible_fuzzer::anchor_spl::token::ID,
            })
            .signers(&[&*f.payer])
            .send()
            .expect("harness-level send() must not error -- only the on-chain tx should fail");
        outcome.logs().to_vec()
    }

    fn assert_dispatches_no_guard_failure_then_wall(logs: &[String]) {
        assert!(
            logs.iter().any(|l| l.contains("Instruction: RemoveLiquidity")),
            "expected the handler to actually dispatch, logs = {:#?}",
            logs
        );
        assert!(
            !logs.iter().any(|l| l.contains("AnchorError")),
            "expected no Anchor guard failure (all guards should pass), logs = {:#?}",
            logs
        );
        assert!(
            logs.iter().any(|l| l.contains("Access violation")),
            "expected the known native-CPI VM wall; if this now fails differently the wall may \
             have moved or been fixed upstream -- re-diagnose, logs = {:#?}",
            logs
        );
    }

    // Default-shaped reserves (both `sol_out_amount` and `msol_out_amount` > 0, matching the
    // plain default fixture's own proportions): proves the guard chain (remove_liquidity.rs:69,
    // 71-72, the `lp_mint_supply <= lp_supply` FALSE-branch tail at :83-89, both `proportional`
    // calls at :92-101, the :103-107 `min_withdraw` guard) and the :114 branch-entry all execute
    // cleanly, then hits this handler's FIRST CPI: the PDA-signed SOL-leg `system_program::
    // transfer` at :116-130. Same harness-wide LiteSVM 0.15.2 native-CPI-dispatch "Access
    // violation ... size 32" wall reproduced this round for create_canonical_stake/merge_stakes/
    // deactivate_stake/withdraw_stake_account/stake_reserve/emergency_unstake/claim/add_liquidity.
    #[test]
    fn remove_liquidity_default_reserves_hit_sol_leg_transfer_wall() {
        let mut f = MarinadeFinanceFixture::setup();
        let logs = send_remove_liquidity_custom(
            &mut f,
            SCOUT_REMOVE_LIQUIDITY_TOKENS,
            SCOUT_REMOVE_LIQUIDITY_SOL_LEG_LAMPORTS,
            SCOUT_REMOVE_LIQUIDITY_MSOL_LEG_AMOUNT,
            SCOUT_REMOVE_LIQUIDITY_LP_SUPPLY,
            1,
        );
        assert_dispatches_no_guard_failure_then_wall(&logs);
    }

    // Starves the SOL leg (50 lamports; `proportional(10, 50, 1000)` floors to 0) so :114's
    // `sol_out_amount > 0` is FALSE and the SOL-leg transfer branch is skipped entirely, while
    // the mSOL leg keeps its default (nonzero) balance so :133's `msol_out_amount > 0` is TRUE --
    // proving this handler's SECOND CPI, the PDA-signed mSOL-leg `transfer_token` at :135-150, is
    // independently reachable (not merely downstream of the first wall) and hits the identical
    // fault there instead.
    #[test]
    fn remove_liquidity_starved_sol_leg_hits_msol_leg_transfer_wall() {
        let mut f = MarinadeFinanceFixture::setup();
        let logs = send_remove_liquidity_custom(
            &mut f,
            SCOUT_REMOVE_LIQUIDITY_TOKENS,
            50,
            SCOUT_REMOVE_LIQUIDITY_MSOL_LEG_AMOUNT,
            SCOUT_REMOVE_LIQUIDITY_LP_SUPPLY,
            0,
        );
        assert_dispatches_no_guard_failure_then_wall(&logs);
    }

    // Starves BOTH legs (50 lamports / 50 mSOL; both `proportional(10, 50, 1000)` calls floor to
    // 0) so :114 and :133 are both FALSE and neither conditional transfer runs -- proving the
    // handler's THIRD, UNCONDITIONAL CPI, the LP `burn` at :153-163, is reached on its own (not
    // merely as a downstream consequence of the other two walls) and hits the identical fault
    // there. Together with the two tests above, every one of this handler's three CPI dispatch
    // points is independently proven reachable and independently proven blocked by the same
    // environment wall.
    #[test]
    fn remove_liquidity_starved_both_legs_hits_burn_wall() {
        let mut f = MarinadeFinanceFixture::setup();
        let logs = send_remove_liquidity_custom(
            &mut f,
            SCOUT_REMOVE_LIQUIDITY_TOKENS,
            50,
            50,
            SCOUT_REMOVE_LIQUIDITY_LP_SUPPLY,
            0,
        );
        assert_dispatches_no_guard_failure_then_wall(&logs);
    }

    // Corrected replacement for `remove_liquidity_setup_glue_tests::remove_liquidity_covers_
    // unregistered_lp_supply_log_branch`, which asserts full success on the `lp_mint_supply >
    // self.state.liq_pool.lp_supply` TRUE branch (:83, the "Someone minted lp tokens without our
    // permission or bug found" `msg!` at :85) -- now proven stale by the same wall. Mints the LP
    // mint with its real supply (`lp_supply`) but sets `liq_pool.lp_supply` one lower, so the
    // mint-side supply is strictly greater and the TRUE branch is taken (as opposed to every
    // other test in this module, which takes the FALSE/`else` branch at :86-89) before falling
    // through to the same SOL-leg transfer wall as the default-reserves test above.
    #[test]
    fn remove_liquidity_unregistered_lp_supply_branch_then_hits_wall() {
        let mut f = MarinadeFinanceFixture::setup();
        let logs = send_remove_liquidity_custom_with_mint_supply(
            &mut f,
            SCOUT_REMOVE_LIQUIDITY_TOKENS,
            SCOUT_REMOVE_LIQUIDITY_SOL_LEG_LAMPORTS,
            SCOUT_REMOVE_LIQUIDITY_MSOL_LEG_AMOUNT,
            SCOUT_REMOVE_LIQUIDITY_LP_SUPPLY - 1,
            SCOUT_REMOVE_LIQUIDITY_LP_SUPPLY,
            1,
        );
        assert_dispatches_no_guard_failure_then_wall(&logs);
    }

    // Corrected replacement for `remove_liquidity_zero_supply_denominator_tests::remove_liquidity_
    // zero_tokens_reaches_denominator_zero_and_skip_transfers`, which asserts full success -- now
    // proven stale by the same wall. `lp_supply = 0` drives BOTH `proportional(...)` calls
    // (:92-101) into calc.rs:12-13's `denominator == 0` EARLY-RETURN branch (`Ok(amount)`, i.e.
    // `Ok(tokens)` = `Ok(0)`), a genuinely different code path than the two starved-leg tests
    // above (which floor a nonzero-denominator division down to 0 instead) -- distinct line
    // coverage in shared `proportional()`. Both `sol_out_amount`/`msol_out_amount` land on 0, so
    // both conditional transfer branches (:114, :133) are skipped, falling through to the same
    // unconditional `burn` CPI wall as `remove_liquidity_starved_both_legs_hits_burn_wall`.
    #[test]
    fn remove_liquidity_zero_lp_supply_denominator_zero_then_hits_burn_wall() {
        let mut f = MarinadeFinanceFixture::setup();
        let logs = send_remove_liquidity_custom(&mut f, 0, 500_000_000, 500_000_000, 0, 0);
        assert_dispatches_no_guard_failure_then_wall(&logs);
    }
}

#[cfg(test)]
mod emergency_unstake_native_cpi_wall_tests {
    use super::*;

    fn send_emergency_unstake_logs(f: &mut MarinadeFinanceFixture) -> Vec<String> {
        let state = scout_emergency_unstake_state(f.program_id);
        let stake_deposit_authority =
            Pubkey::find_program_address(&[state.as_ref(), SCOUT_STAKE_DEPOSIT_SEED], &f.program_id).0;
        let outcome = f
            .ctx
            .program(f.program_id)
            .call(instruction::EmergencyUnstake {
                stake_index: 0,
                validator_index: 0,
            })
            .accounts(accounts::EmergencyUnstake {
                state,
                validator_manager_authority: f.payer.pubkey(),
                validator_list: scout_emergency_unstake_validator_list(f.program_id),
                stake_list: scout_emergency_unstake_stake_list(f.program_id),
                stake_account: scout_emergency_unstake_stake_account(f.program_id),
                stake_deposit_authority,
                clock: crucible_fuzzer::anchor_lang::solana_program::sysvar::clock::ID,
                stake_program: crucible_fuzzer::anchor_spl::stake::ID,
            })
            .signers(&[&*f.payer])
            .send()
            .expect("harness-level send() must not error -- only the on-chain tx should fail");
        outcome.logs().to_vec()
    }

    // From a fresh, all-guards-satisfied setup, every guard in emergency_unstake.rs:52-85
    // (paused, delinquent_upgrader, stake.last_update_status==Active, !is_emergency_unstaking,
    // validator.score==0) plus check_stake_amount_and_validator's delegation/voter-pubkey/
    // updated-balance checks (checks.rs:95-112, invoked at :88-92) and State::on_stake_moved's
    // stake-moved-cap guard (state/mod.rs:293-303, invoked at :95) all execute with zero
    // AnchorErrors, reaching this handler's ONE AND ONLY CPI: the unconditional, PDA-signed
    // native `deactivate_stake` invoke_signed at :97-109. That's exactly the same harness-wide
    // LiteSVM 0.15.2 native-CPI-dispatch "Access violation ... size 32" fault already
    // independently reproduced this round for create_canonical_stake/merge_stakes/
    // remove_liquidity/deactivate_stake/withdraw_stake_account/stake_reserve/claim/add_liquidity --
    // an environment wall, not a setup-glue gap. Everything strictly downstream (:111-137: the
    // `is_emergency_unstaking`/`last_update_status` writes, the `active_balance`/
    // `total_active_balance` updates, `emergency_cooling_down +=`, the `stake_system.set`/
    // `validator_system.set` writes, and the final `Ok(())`) is unreachable behind this wall.
    #[test]
    fn emergency_unstake_reaches_first_native_cpi_wall_from_fresh_setup() {
        let mut fixture = MarinadeFinanceFixture::setup();
        let logs = send_emergency_unstake_logs(&mut fixture);
        assert!(
            logs.iter().any(|l| l.contains("Instruction: EmergencyUnstake")),
            "expected the handler to actually dispatch, logs = {:#?}",
            logs
        );
        assert!(
            !logs.iter().any(|l| l.contains("AnchorError")),
            "expected no Anchor guard failure (all guards should pass), logs = {:#?}",
            logs
        );
        assert!(
            logs.iter().any(|l| l.contains("Access violation")),
            "expected the known native-CPI VM wall; if this now fails differently the wall may \
             have moved or been fixed upstream -- re-diagnose, logs = {:#?}",
            logs
        );
    }
}

