#[cfg(test)]
mod add_liquidity_native_cpi_wall_tests {
    use super::*;

    // Uses the exact same fixture path as `action_add_liquidity` (scout_prepare_add_liquidity_action
    // + scout_refill_add_liquidity_transfer_from), captured via a direct instruction call so the
    // transaction logs -- not just is_success() -- are observable.
    fn send_default_add_liquidity_logs(fixture: &mut MarinadeFinanceFixture) -> Vec<String> {
        let lamports = SCOUT_ADD_LIQUIDITY_LAMPORTS;
        let state = { scout_prepare_add_liquidity_action(fixture); fixture.state };
        let lp_mint = scout_add_liquidity_lp_mint(fixture.state, fixture.program_id);
        let lp_mint_authority = Pubkey::find_program_address(
            &[fixture.state.as_ref(), SCOUT_LP_MINT_AUTHORITY_SEED],
            &fixture.program_id,
        )
        .0;
        let transfer_from = scout_refill_add_liquidity_transfer_from(fixture);
        let mint_to = scout_add_liquidity_mint_to(fixture.state, fixture.program_id);
        let outcome = fixture
            .ctx
            .program(fixture.program_id)
            .call(instruction::AddLiquidity { lamports })
            .accounts(accounts::AddLiquidity {
                state,
                lp_mint,
                lp_mint_authority,
                liq_pool_msol_leg: fixture.liq_pool_msol_leg,
                liq_pool_sol_leg_pda: fixture.liq_pool_sol_leg_pda,
                transfer_from,
                mint_to,
                system_program: system_program::ID,
                token_program: crucible_fuzzer::anchor_spl::token::ID,
            })
            .signers(&[&*fixture.payer])
            .send()
            .expect("harness-level send() must not error -- only the on-chain tx should fail");
        outcome.logs().to_vec()
    }

    // From a fresh, all-guards-satisfied setup (the same one `action_add_liquidity` uses), every
    // guard (add_liquidity.rs:66 `!paused`, :68-72 `min_deposit`, :74-78 `user_sol_balance`,
    // :86-90 `UnregisteredLPMinted`) and every pre-CPI computation (:73 `user_sol_balance`, :81
    // `check_liquidity_cap`, :94-105 the value/price math, :113-114 `shares_from_value`) execute
    // cleanly with zero AnchorErrors, reaching this handler's FIRST CPI: the plain, unsigned
    // `system_program::transfer` from `transfer_from` to `liq_pool_sol_leg_pda` at :120-129. That
    // is exactly the same harness-wide LiteSVM 0.15.2 native-CPI-dispatch "Access violation ...
    // size 32" fault already independently reproduced this round for
    // create_canonical_stake/merge_stakes/remove_liquidity/emergency_unstake/deactivate_stake/
    // withdraw_stake_account/stake_reserve/claim/order_unstake -- an environment wall, not a
    // setup-glue gap. Everything strictly downstream of :129 (the signed `mint_to` CPI at
    // :133-148, `on_lp_mint` at :149, the `AddLiquidityEvent` emit at :151-163, `Ok(())` at :165)
    // is unreachable behind this wall regardless of how setup() is constructed.
    #[test]
    fn add_liquidity_reaches_first_native_cpi_wall_from_fresh_setup() {
        let mut fixture = MarinadeFinanceFixture::setup();
        let logs = send_default_add_liquidity_logs(&mut fixture);
        assert!(
            logs.iter().any(|l| l.contains("Instruction: AddLiquidity")),
            "expected the handler to actually dispatch, logs = {:#?}",
            logs
        );
        assert!(
            !logs.iter().any(|l| l.contains("AnchorError")),
            "expected no Anchor guard failure (all guards should pass), logs = {:#?}",
            logs
        );
        assert!(
            logs.iter().any(|l| l.contains("Access violation")),
            "expected the known native-CPI VM wall; if this now fails differently the wall may \
             have moved or been fixed upstream -- re-diagnose, logs = {:#?}",
            logs
        );
    }
}

#[cfg(test)]
mod add_liquidity_real_calc_overflow_tests {
    use super::*;

    #[test]
    fn add_liquidity_rejects_genuine_share_calculation_overflow() {
        let mut fixture = MarinadeFinanceFixture::setup();
        scout_prepare_add_liquidity_tail_success_action(&mut fixture);

        let lp_mint = scout_add_liquidity_lp_mint(fixture.state, fixture.program_id);
        let lp_mint_authority = Pubkey::find_program_address(
            &[fixture.state.as_ref(), SCOUT_LP_MINT_AUTHORITY_SEED],
            &fixture.program_id,
        )
        .0;
        // Real, nonzero lp_mint supply -- so shares_from_value's `total_shares != 0` branch
        // (calc.rs:29) is taken instead of the `Ok(value)` early return (calc.rs:25-27).
        fixture
            .ctx
            .create_mint()
            .pubkey(lp_mint)
            .mint_authority(lp_mint_authority)
            .supply(u64::MAX)
            .decimals(9)
            .freeze_authority(None)
            .create()
            .unwrap();

        let mut state = fixture
            .ctx
            .read_anchor_account::<marinade_finance::state::State>(&fixture.state)
            .unwrap();
        // Must be >= lp_mint.supply to clear the :86-90 UnregisteredLPMinted guard; process()
        // then overwrites this with lp_mint.supply (u64::MAX) at :92 regardless.
        state.liq_pool.lp_supply = u64::MAX;
        state.liq_pool.liquidity_sol_cap = u64::MAX;
        state.rent_exempt_for_token_acc = 0;
        fixture
            .ctx
            .create_account()
            .pubkey(fixture.state)
            .owner(fixture.program_id)
            .data(&scout_state_data(&state))
            .create()
            .unwrap();
        // Tiny total_liq_pool_value (sol leg = 1 lamport, msol leg = 0) so
        // amount(lamports) * numerator(total_shares=u64::MAX) / denominator(total_value=1)
        // vastly exceeds u64::MAX.
        fixture
            .ctx
            .create_token_account()
            .pubkey(fixture.liq_pool_msol_leg)
            .mint(fixture.msol_mint)
            .token_owner(fixture.liq_pool_msol_leg_authority)
            .amount(0)
            .create()
            .unwrap();
        fixture
            .ctx
            .create_account()
            .pubkey(fixture.liq_pool_sol_leg_pda)
            .owner(system_program::ID)
            .lamports(1)
            .create()
            .unwrap();

        let outcome = fixture
            .ctx
            .program(fixture.program_id)
            .call(instruction::AddLiquidity {
                lamports: SCOUT_ADD_LIQUIDITY_LAMPORTS,
            })
            .accounts(accounts::AddLiquidity {
                state: fixture.state,
                lp_mint,
                lp_mint_authority,
                liq_pool_msol_leg: fixture.liq_pool_msol_leg,
                liq_pool_sol_leg_pda: fixture.liq_pool_sol_leg_pda,
                transfer_from: fixture.payer.pubkey(),
                mint_to: scout_add_liquidity_mint_to(fixture.state, fixture.program_id),
                system_program: system_program::ID,
                token_program: crucible_fuzzer::anchor_spl::token::ID,
            })
            .signers(&[&*fixture.payer])
            .send()
            .expect("harness-level send() must not error -- only the on-chain tx should fail");
        let logs = outcome.logs().to_vec();
        assert!(
            !outcome.is_success(),
            "expected CalculationFailure, logs = {:#?}",
            logs
        );
        assert!(
            !logs.iter().any(|l| l.contains("Access violation")),
            "expected a real CalculationFailure BEFORE the native-CPI wall, not the wall itself \
             -- if this fires, the overflow construction stopped working, logs = {:#?}",
            logs
        );
        assert!(
            logs.iter().any(|l| l.contains("CalculationFailure")
                || l.contains("MarinadeError::CalculationFailure")),
            "expected the specific CalculationFailure error, logs = {:#?}",
            logs
        );
    }
}
