mod solana_stake_interface {
    use super::Pubkey;
    use std::io::{Result as IoResult, Write};

    pub mod program {
        pub const ID: super::Pubkey =
            solana_pubkey::pubkey!("Stake11111111111111111111111111111111111111");
    }

    pub mod stake_flags {
        #[derive(Clone, Copy, Default)]
        pub struct StakeFlags;

        impl StakeFlags {
            pub fn empty() -> Self {
                Self
            }
        }
    }

    pub mod state {
        use super::{stake_flags::StakeFlags, IoResult, Pubkey, Write};

        pub const DEFAULT_WARMUP_COOLDOWN_RATE: f64 = 0.25;

        #[derive(Clone, Copy, Default)]
        pub struct Lockup {
            pub unix_timestamp: i64,
            pub epoch: u64,
            pub custodian: Pubkey,
        }

        #[derive(Clone, Copy)]
        pub struct Authorized {
            pub staker: Pubkey,
            pub withdrawer: Pubkey,
        }

        impl Authorized {
            pub fn auto(authority: &Pubkey) -> Self {
                Self {
                    staker: *authority,
                    withdrawer: *authority,
                }
            }
        }

        #[derive(Clone, Copy)]
        pub struct Meta {
            pub rent_exempt_reserve: u64,
            pub authorized: Authorized,
            pub lockup: Lockup,
        }

        #[derive(Clone, Copy)]
        pub struct Delegation {
            pub voter_pubkey: Pubkey,
            pub stake: u64,
            pub activation_epoch: u64,
            pub deactivation_epoch: u64,
            pub warmup_cooldown_rate: f64,
        }

        #[derive(Clone, Copy)]
        pub struct Stake {
            pub delegation: Delegation,
            pub credits_observed: u64,
        }

        pub enum StakeStateV2 {
            Initialized(Meta),
            Stake(Meta, Stake, StakeFlags),
        }

        impl StakeStateV2 {
            pub fn size_of() -> usize {
                200
            }

            pub fn serialize<W: Write>(&self, writer: &mut W) -> IoResult<()> {
                match self {
                    Self::Initialized(meta) => {
                        writer.write_all(&1u32.to_le_bytes())?;
                        write_meta(writer, meta)
                    }
                    Self::Stake(meta, stake, _flags) => {
                        writer.write_all(&2u32.to_le_bytes())?;
                        write_meta(writer, meta)?;
                        writer.write_all(stake.delegation.voter_pubkey.as_ref())?;
                        writer.write_all(&stake.delegation.stake.to_le_bytes())?;
                        writer.write_all(&stake.delegation.activation_epoch.to_le_bytes())?;
                        writer.write_all(&stake.delegation.deactivation_epoch.to_le_bytes())?;
                        writer.write_all(&stake.delegation.warmup_cooldown_rate.to_le_bytes())?;
                        writer.write_all(&stake.credits_observed.to_le_bytes())
                    }
                }
            }
        }

        fn write_meta<W: Write>(writer: &mut W, meta: &Meta) -> IoResult<()> {
            writer.write_all(&meta.rent_exempt_reserve.to_le_bytes())?;
            writer.write_all(meta.authorized.staker.as_ref())?;
            writer.write_all(meta.authorized.withdrawer.as_ref())?;
            writer.write_all(&meta.lockup.unix_timestamp.to_le_bytes())?;
            writer.write_all(&meta.lockup.epoch.to_le_bytes())?;
            writer.write_all(meta.lockup.custodian.as_ref())
        }
    }
}

fn scout_change_authority_pubkey(tag: u8, n: u64) -> Pubkey {
    let mut bytes = [tag; 32];
    bytes[1..9].copy_from_slice(&n.to_le_bytes());
    Pubkey::new_from_array(bytes)
}

fn scout_change_authority_data(
    n: u64,
    admin_authority: Pubkey,
) -> marinade_finance::types::ChangeAuthorityData {
    marinade_finance::types::ChangeAuthorityData {
        admin: if n & 1 == 0 {
            Some(admin_authority)
        } else {
            None
        },
        validator_manager: if n & 2 == 0 {
            Some(scout_change_authority_pubkey(1, n))
        } else {
            None
        },
        operational_sol_account: if n & 4 == 0 {
            Some(scout_change_authority_pubkey(2, n))
        } else {
            None
        },
        treasury_msol_account: if n & 8 == 0 {
            Some(scout_change_authority_pubkey(3, n))
        } else {
            None
        },
        pause_authority: if n & 16 == 0 {
            Some(scout_change_authority_pubkey(4, n))
        } else {
            None
        },
    }
}

fn scout_state_account_bytes(admin_authority: Pubkey) -> Vec<u8> {
    let mut state = marinade_finance::types::State::default();
    state.admin_authority = admin_authority;
    state.validator_system.manager_authority = admin_authority;
    state.msol_price = 0x1_0000_0000;
    state.min_deposit = 1;
    state.min_withdraw = 1;
    state.staking_sol_cap = u64::MAX;
    state.max_stake_moved_per_epoch.basis_points = 10_000;
    state.delinquent_upgrader = marinade_finance::types::DelinquentUpgraderState::Done;

    let mut bytes = marinade_finance::state::State::DISCRIMINATOR.to_vec();
    state.serialize(&mut bytes).unwrap();
    bytes
}
