fn scout_marinade_state(
    state: Pubkey,
    validator_list: Pubkey,
    stake_list: Pubkey,
    payer: Pubkey,
) -> marinade_finance::state::State {
    let (_reserve, reserve_bump_seed) =
        Pubkey::find_program_address(&[state.as_ref(), SCOUT_RESERVE_SEED], &marinade_finance::ID);
    let (_msol_mint_authority, msol_mint_authority_bump_seed) = Pubkey::find_program_address(
        &[state.as_ref(), SCOUT_MSOL_MINT_AUTHORITY_SEED],
        &marinade_finance::ID,
    );
    let (_stake_deposit_authority, stake_deposit_bump_seed) = Pubkey::find_program_address(
        &[state.as_ref(), SCOUT_STAKE_DEPOSIT_SEED],
        &marinade_finance::ID,
    );
    let (_stake_withdraw_authority, stake_withdraw_bump_seed) = Pubkey::find_program_address(
        &[state.as_ref(), SCOUT_STAKE_WITHDRAW_SEED],
        &marinade_finance::ID,
    );
    let (lp_mint_authority, lp_mint_authority_bump_seed) = Pubkey::find_program_address(
        &[state.as_ref(), SCOUT_LP_MINT_AUTHORITY_SEED],
        &marinade_finance::ID,
    );
    let (liq_pool_sol_leg, sol_leg_bump_seed) = Pubkey::find_program_address(
        &[state.as_ref(), SCOUT_LIQ_POOL_SOL_LEG_SEED],
        &marinade_finance::ID,
    );
    let (liq_pool_msol_leg_authority, msol_leg_authority_bump_seed) = Pubkey::find_program_address(
        &[state.as_ref(), SCOUT_LIQ_POOL_MSOL_LEG_AUTHORITY_SEED],
        &marinade_finance::ID,
    );

    marinade_finance::state::State {
        msol_mint: lp_mint_authority,
        admin_authority: payer,
        operational_sol_account: payer,
        treasury_msol_account: Pubkey::new_unique(),
        reserve_bump_seed,
        msol_mint_authority_bump_seed,
        rent_exempt_for_token_acc: 0,
        reward_fee: scout_fee(0),
        stake_system: marinade_finance::types::StakeSystem {
            stake_list: scout_list(stake_list, 1, 0),
            delayed_unstake_cooling_down: 0,
            stake_deposit_bump_seed,
            stake_withdraw_bump_seed,
            slots_for_stake_delta: 3_000,
            last_stake_delta_epoch: u64::MAX,
            min_stake: 10_000_000,
            extra_stake_delta_runs: 0,
        },
        validator_system: marinade_finance::types::ValidatorSystem {
            validator_list: scout_list(validator_list, SCOUT_VALIDATOR_RECORD_SIZE, 0),
            manager_authority: payer,
            total_validator_score: 0,
            total_active_balance: 0,
            auto_add_validator_enabled: 0,
        },
        liq_pool: marinade_finance::types::LiqPool {
            lp_mint: lp_mint_authority,
            lp_mint_authority_bump_seed,
            sol_leg_bump_seed,
            msol_leg_authority_bump_seed,
            msol_leg: liq_pool_msol_leg_authority,
            lp_liquidity_target: 50_000_000_000,
            lp_max_fee: scout_fee(1_000),
            lp_min_fee: scout_fee(0),
            treasury_cut: scout_fee(0),
            lp_supply: 0,
            lent_from_sol_leg: 0,
            liquidity_sol_cap: u64::MAX,
        },
        available_reserve_balance: 0,
        msol_supply: 0,
        msol_price: 0x1_0000_0000,
        circulating_ticket_count: 0,
        circulating_ticket_balance: 0,
        lent_from_reserve: 0,
        min_deposit: 1,
        min_withdraw: 1,
        staking_sol_cap: u64::MAX,
        emergency_cooling_down: 0,
        pause_authority: payer,
        paused: false,
        delayed_unstake_fee: scout_fee_cents(0),
        withdraw_stake_account_fee: scout_fee_cents(0),
        withdraw_stake_account_enabled: false,
        last_stake_move_epoch: 0,
        stake_moved: 0,
        max_stake_moved_per_epoch: scout_fee(10_000),
        delinquent_upgrader: marinade_finance::types::DelinquentUpgraderState::Done,
        deposit_sol_fee: scout_fee_cents(0),
        deposit_stake_account_fee: scout_fee_cents(0),
    }
}
