fn scout_claim_state_data(state: &marinade_finance::state::State) -> Vec<u8> {
    let mut data = marinade_finance::state::State::DISCRIMINATOR.to_vec();
    state.serialize(&mut data).unwrap();
    data
}

fn scout_claim_ticket_account_data(
    state_address: Pubkey,
    beneficiary: Pubkey,
    lamports_amount: u64,
    created_epoch: u64,
) -> Vec<u8> {
    let ticket = marinade_finance::state::TicketAccountData {
        state_address,
        beneficiary,
        lamports_amount,
        created_epoch,
    };
    let mut data = marinade_finance::state::TicketAccountData::DISCRIMINATOR.to_vec();
    ticket.serialize(&mut data).unwrap();
    data
}
const SCOUT_REMOVE_LIQUIDITY_TOKENS: u64 = 10;
const SCOUT_REMOVE_LIQUIDITY_LP_SUPPLY: u64 = 1_000;
