use anchor_lang::AnchorDeserialize;

const SCOUT_STAKE_RESERVE_VALIDATOR_SCORE: u32 = 11;

fn scout_read_marinade_state(
    ctx: &crate::__scout_crucible_test_context::TestContext,
    state: &Pubkey,
) -> marinade_finance::state::State {
    let account = ctx.read_account(state).unwrap();
    let disc_len = marinade_finance::state::State::DISCRIMINATOR.len();
    assert_eq!(
        &account.data[..disc_len],
        marinade_finance::state::State::DISCRIMINATOR
    );
    marinade_finance::state::State::deserialize(&mut &account.data[disc_len..]).unwrap()
}

fn scout_stake_reserve_stake_list(
    ctx: &crate::__scout_crucible_test_context::TestContext,
    state: &Pubkey,
) -> Pubkey {
    scout_read_marinade_state(ctx, state)
        .stake_system
        .stake_list
        .account
}

fn scout_prepare_stake_reserve_fixture(fixture: &mut MarinadeFinanceFixture) {
    let stake_list = Pubkey::new_unique();
    let (reserve_pda, reserve_bump_seed) =
        Pubkey::find_program_address(&[fixture.state.as_ref(), SCOUT_RESERVE_SEED], &fixture.program_id);
    let (_stake_deposit_authority, stake_deposit_bump_seed) =
        Pubkey::find_program_address(&[fixture.state.as_ref(), SCOUT_STAKE_DEPOSIT_SEED], &fixture.program_id);
    let (_stake_withdraw_authority, stake_withdraw_bump_seed) =
        Pubkey::find_program_address(&[fixture.state.as_ref(), SCOUT_STAKE_WITHDRAW_SEED], &fixture.program_id);
    let (validator_record, _duplication_flag, duplication_flag_bump_seed) =
        scout_validator_record(
            fixture.state,
            fixture.validator_vote,
            fixture.program_id,
            SCOUT_STAKE_RESERVE_VALIDATOR_SCORE,
        );
    let mut state = scout_read_marinade_state(&fixture.ctx, &fixture.state);
    state.reserve_bump_seed = reserve_bump_seed;
    state.stake_system.stake_list = scout_list(stake_list, SCOUT_STAKE_RECORD_SIZE, 0);
    state.stake_system.stake_deposit_bump_seed = stake_deposit_bump_seed;
    state.stake_system.stake_withdraw_bump_seed = stake_withdraw_bump_seed;
    state.stake_system.last_stake_delta_epoch = u64::MAX;
    state.stake_system.extra_stake_delta_runs = 0;
    state.validator_system.validator_list = scout_list(
        fixture.validator_list,
        SCOUT_VALIDATOR_RECORD_SIZE,
        1,
    );
    state.validator_system.total_validator_score = SCOUT_STAKE_RESERVE_VALIDATOR_SCORE;
    state.validator_system.total_active_balance = 0;
    state.paused = false;
    state.delinquent_upgrader = marinade_finance::types::DelinquentUpgraderState::Done;
    state.available_reserve_balance = 0;
    state.circulating_ticket_balance = 0;
    state.emergency_cooling_down = 0;
    state.stake_system.delayed_unstake_cooling_down = 0;
    state.rent_exempt_for_token_acc = 0;
    let state_data = scout_state_data(&state);
    let mut state_account = fixture.ctx.read_account(&fixture.state).unwrap();
    state_account.owner = fixture.program_id;
    state_account.data = state_data;
    fixture.ctx.write_account(&fixture.state, state_account).unwrap();

    let mut validator_list_data = scout_validator_list_data(&[validator_record]);
    validator_list_data.resize(
        8 + SCOUT_VALIDATOR_RECORD_SIZE * SCOUT_VALIDATOR_LIST_CAPACITY,
        0,
    );
    fixture
        .ctx
        .create_account()
        .pubkey(fixture.validator_list)
        .owner(fixture.program_id)
        .data(&validator_list_data)
        .create()
        .unwrap();
    let mut stake_list_data = SCOUT_STAKE_LIST_DISCRIMINATOR.to_vec();
    stake_list_data.resize(
        8 + SCOUT_STAKE_RECORD_SIZE * SCOUT_STAKE_LIST_CAPACITY,
        0,
    );
    fixture
        .ctx
        .create_account()
        .pubkey(stake_list)
        .owner(fixture.program_id)
        .data(&stake_list_data)
        .create()
        .unwrap();
    fixture
        .ctx
        .create_account()
        .pubkey(reserve_pda)
        .owner(system_program::ID)
        .lamports(0)
        .create()
        .unwrap();
    fixture
        .ctx
        .create_account()
        .pubkey(fixture.validator_vote)
        .owner(system_program::ID)
        .data(&[1])
        .create()
        .unwrap();
    let _ = duplication_flag_bump_seed;
}

fn scout_write_marinade_state(
    ctx: &mut crate::__scout_crucible_test_context::TestContext,
    state: Pubkey,
    value: &marinade_finance::state::State,
) {
    let mut account = ctx.read_account(&state).unwrap();
    account.owner = marinade_finance::ID;
    account.data = scout_state_data(value);
    ctx.write_account(&state, account).unwrap();
}

