const SCOUT_PARTIAL_UNSTAKE_STAKE_LAMPORTS: u64 = 100_000_000;
const SCOUT_PARTIAL_UNSTAKE_AMOUNT: u64 = 20_000_000;
const SCOUT_PARTIAL_UNSTAKE_MIN_STAKE: u64 = 10_000_000;
const SCOUT_PARTIAL_UNSTAKE_VALIDATOR_SCORE: u32 = 10;

fn scout_partial_unstake_deposit_authority(state: Pubkey, program_id: Pubkey) -> Pubkey {
    Pubkey::find_program_address(&[state.as_ref(), SCOUT_STAKE_DEPOSIT_SEED], &program_id).0
}

fn scout_partial_unstake_reserve_pda(state: Pubkey, program_id: Pubkey) -> Pubkey {
    Pubkey::find_program_address(&[state.as_ref(), SCOUT_RESERVE_SEED], &program_id).0
}

fn scout_partial_unstake_stake_record(
    stake_account: Pubkey,
    delegated_lamports: u64,
    deactivating: bool,
    is_emergency_unstaking: bool,
) -> marinade_finance::types::StakeRecord {
    marinade_finance::types::StakeRecord {
        stake_account,
        last_update_delegated_lamports: delegated_lamports,
        last_update_epoch: 0,
        is_emergency_unstaking,
        last_update_status: if deactivating {
            marinade_finance::types::StakeStatus::Deactivating
        } else {
            marinade_finance::types::StakeStatus::Active
        },
    }
}

fn scout_partial_unstake_stake_list_data(
    stake_account: Pubkey,
    delegated_lamports: u64,
    deactivating: bool,
    is_emergency_unstaking: bool,
) -> Vec<u8> {
    let record = scout_partial_unstake_stake_record(
        stake_account,
        delegated_lamports,
        deactivating,
        is_emergency_unstaking,
    );
    let mut record_bytes = Vec::new();
    record.serialize(&mut record_bytes).unwrap();
    assert_eq!(record_bytes.len(), SCOUT_STAKE_RECORD_SIZE);
    let mut bytes = vec![0u8; 8 + SCOUT_STAKE_RECORD_SIZE * SCOUT_STAKE_LIST_CAPACITY];
    bytes[..8].copy_from_slice(SCOUT_STAKE_LIST_DISCRIMINATOR);
    bytes[8..8 + SCOUT_STAKE_RECORD_SIZE].copy_from_slice(&record_bytes);
    bytes
}

fn scout_partial_unstake_validator_record(
    state: Pubkey,
    validator_vote: Pubkey,
    program_id: Pubkey,
    active_balance: u64,
) -> marinade_finance::types::ValidatorRecord {
    let (_, duplication_flag_bump_seed) = Pubkey::find_program_address(
        &[state.as_ref(), SCOUT_DUPLICATE_FLAG_SEED, validator_vote.as_ref()],
        &program_id,
    );
    marinade_finance::types::ValidatorRecord {
        validator_account: validator_vote,
        active_balance,
        score: SCOUT_PARTIAL_UNSTAKE_VALIDATOR_SCORE,
        last_stake_delta_epoch: u64::MAX,
        duplication_flag_bump_seed,
        delinquent_upgrader_active_balance: 0,
    }
}

