fn scout_partial_unstake_write_state_account(
    f: &mut MarinadeFinanceFixture,
    state_value: &marinade_finance::state::State,
) {
    let state_data = scout_state_data(state_value);
    f.ctx
        .create_account()
        .pubkey(f.partial_unstake_state)
        .owner(f.program_id)
        .data(&state_data)
        .create()
        .unwrap();
}

fn scout_partial_unstake_rewrite_state(
    f: &mut MarinadeFinanceFixture,
    edit: impl FnOnce(&mut marinade_finance::state::State),
) {
    let mut state = f
        .ctx
        .read_anchor_account::<marinade_finance::state::State>(&f.partial_unstake_state)
        .unwrap();
    edit(&mut state);
    scout_partial_unstake_write_state_account(f, &state);
}

fn scout_partial_unstake_write_stake_list_record(
    f: &mut MarinadeFinanceFixture,
    delegated_lamports: u64,
    deactivating: bool,
    is_emergency_unstaking: bool,
) {
    let stake_list_data = scout_partial_unstake_stake_list_data(
        f.partial_unstake_stake_account,
        delegated_lamports,
        deactivating,
        is_emergency_unstaking,
    );
    f.ctx
        .create_account()
        .pubkey(f.partial_unstake_stake_list)
        .owner(f.program_id)
        .data(&stake_list_data)
        .create()
        .unwrap();
}

fn scout_partial_unstake_write_stake_account(
    f: &mut MarinadeFinanceFixture,
    validator_vote: Pubkey,
    stake_lamports: u64,
) {
    let stake_deposit_authority =
        scout_partial_unstake_deposit_authority(f.partial_unstake_state, f.program_id);
    let stake_account_data = scout_deposit_stake_account_data(
        stake_deposit_authority,
        stake_deposit_authority,
        validator_vote,
        stake_lamports,
        0,
        0,
        u64::MAX,
        solana_stake_interface::state::Lockup::default(),
    );
    f.ctx
        .create_account()
        .pubkey(f.partial_unstake_stake_account)
        .owner(solana_stake_interface::program::ID)
        .lamports(stake_lamports)
        .data(&stake_account_data)
        .create()
        .unwrap();
}

trait ScoutPartialUnstakeSetupGlue {
    fn scout_with_partial_unstake_glue(self) -> Self;
}

impl ScoutPartialUnstakeSetupGlue for MarinadeFinanceFixture {
    fn scout_with_partial_unstake_glue(mut self) -> Self {
        let validator_record = scout_partial_unstake_validator_record(
            self.partial_unstake_state,
            self.partial_unstake_validator_vote,
            self.program_id,
            SCOUT_PARTIAL_UNSTAKE_STAKE_LAMPORTS,
        );
        let validator_list_data = scout_validator_list_data(&[validator_record]);
        let stake_list_data = scout_partial_unstake_stake_list_data(
            self.partial_unstake_stake_account,
            SCOUT_PARTIAL_UNSTAKE_STAKE_LAMPORTS,
            false,
            false,
        );
        let state_value = scout_partial_unstake_state_value(
            self.payer.pubkey(),
            self.program_id,
            self.partial_unstake_state,
            self.partial_unstake_validator_list,
            self.partial_unstake_stake_list,
            SCOUT_PARTIAL_UNSTAKE_STAKE_LAMPORTS,
            SCOUT_PARTIAL_UNSTAKE_AMOUNT,
        );

        scout_partial_unstake_write_state_account(&mut self, &state_value);
        self.ctx
            .create_account()
            .pubkey(self.partial_unstake_validator_list)
            .owner(self.program_id)
            .data(&validator_list_data)
            .create()
            .unwrap();
        self.ctx
            .create_account()
            .pubkey(self.partial_unstake_stake_list)
            .owner(self.program_id)
            .data(&stake_list_data)
            .create()
            .unwrap();
        self.ctx
            .create_account()
            .pubkey(self.partial_unstake_reserve_pda)
            .owner(system_program::ID)
            .lamports(0)
            .create()
            .unwrap();
        self.ctx
            .create_account()
            .pubkey(self.partial_unstake_validator_vote)
            .owner(system_program::ID)
            .data(&[1])
            .create()
            .unwrap();
        let partial_unstake_validator_vote = self.partial_unstake_validator_vote;
        scout_partial_unstake_write_stake_account(
            &mut self,
            partial_unstake_validator_vote,
            SCOUT_PARTIAL_UNSTAKE_STAKE_LAMPORTS,
        );
        self
    }
}

