const SCOUT_CREATE_CANONICAL_STAKE_LAMPORTS: u64 = 50_000_000;
const SCOUT_CREATE_CANONICAL_STAKE_SEED: &[u8] = b"canonical_stake";

fn scout_create_canonical_pda(program_id: Pubkey, seed: &[u8]) -> Pubkey {
    Pubkey::find_program_address(&[seed], &program_id).0
}

fn scout_create_canonical_stake_state_address(program_id: Pubkey) -> Pubkey {
    scout_create_canonical_pda(program_id, b"scout_ccs_state")
}

fn scout_create_canonical_validator_list_address(program_id: Pubkey) -> Pubkey {
    scout_create_canonical_pda(program_id, b"scout_ccs_validator_list")
}

fn scout_create_canonical_stake_list_address(program_id: Pubkey) -> Pubkey {
    scout_create_canonical_pda(program_id, b"scout_ccs_stake_list")
}

fn scout_create_canonical_validator_vote() -> Pubkey {
    Pubkey::new_from_array([77; 32])
}

fn scout_create_canonical_source_stake_address(program_id: Pubkey) -> Pubkey {
    scout_create_canonical_pda(program_id, b"scout_ccs_source_stake")
}

fn scout_create_canonical_stake_address(program_id: Pubkey) -> Pubkey {
    let state = scout_create_canonical_stake_state_address(program_id);
    let validator = scout_create_canonical_validator_vote();
    Pubkey::find_program_address(
        &[state.as_ref(), validator.as_ref(), SCOUT_CREATE_CANONICAL_STAKE_SEED],
        &program_id,
    )
    .0
}

fn scout_create_canonical_validator_list_data(program_id: Pubkey) -> Vec<u8> {
    let state = scout_create_canonical_stake_state_address(program_id);
    let validator = scout_create_canonical_validator_vote();
    let record = scout_validator_record_with_bump(
        validator,
        SCOUT_INITIAL_VALIDATOR_SCORE,
        Pubkey::find_program_address(
            &[state.as_ref(), SCOUT_DUPLICATE_FLAG_SEED, validator.as_ref()],
            &program_id,
        )
        .1,
    );
    scout_validator_list_data(&[record])
}

fn scout_create_canonical_stake_record(
    source_stake: Pubkey,
    delegated_lamports: u64,
    epoch: u64,
) -> marinade_finance::types::StakeRecord {
    marinade_finance::types::StakeRecord {
        stake_account: source_stake,
        last_update_delegated_lamports: delegated_lamports,
        last_update_epoch: epoch,
        is_emergency_unstaking: false,
        last_update_status: marinade_finance::types::StakeStatus::Active,
    }
}

fn scout_create_canonical_stake_list_data(
    program_id: Pubkey,
    delegated_lamports: u64,
    epoch: u64,
) -> Vec<u8> {
    let record = scout_create_canonical_stake_record(
        scout_create_canonical_source_stake_address(program_id),
        delegated_lamports,
        epoch,
    );
    let mut data = SCOUT_STAKE_LIST_DISCRIMINATOR.to_vec();
    record.serialize(&mut data).unwrap();
    data.resize(8 + SCOUT_STAKE_RECORD_SIZE * SCOUT_STAKE_LIST_CAPACITY, 0);
    data
}

fn scout_create_canonical_state_account(
    payer: Pubkey,
    program_id: Pubkey,
    paused: bool,
    delinquent_upgrader: marinade_finance::types::DelinquentUpgraderState,
) -> marinade_finance::state::State {
    let state = scout_create_canonical_stake_state_address(program_id);
    let validator_list = scout_create_canonical_validator_list_address(program_id);
    let stake_list = scout_create_canonical_stake_list_address(program_id);
    let mut account = scout_marinade_state(state, validator_list, stake_list, payer);
    account.operational_sol_account = payer;
    account.stake_system.stake_list = scout_list(stake_list, SCOUT_STAKE_RECORD_SIZE, 1);
    account.stake_system.min_stake = 1;
    account.validator_system.validator_list =
        scout_list(validator_list, SCOUT_VALIDATOR_RECORD_SIZE, 1);
    account.validator_system.total_validator_score = SCOUT_INITIAL_VALIDATOR_SCORE;
    account.validator_system.total_active_balance = SCOUT_CREATE_CANONICAL_STAKE_LAMPORTS;
    account.paused = paused;
    account.delinquent_upgrader = delinquent_upgrader;
    account
}

fn scout_create_canonical_state_data(
    payer: Pubkey,
    program_id: Pubkey,
    paused: bool,
    delinquent_upgrader: marinade_finance::types::DelinquentUpgraderState,
) -> Vec<u8> {
    scout_state_data(&scout_create_canonical_state_account(
        payer,
        program_id,
        paused,
        delinquent_upgrader,
    ))
}

fn scout_create_canonical_source_stake_data(
    program_id: Pubkey,
    delegated_lamports: u64,
    account_lamports: u64,
    deactivation_epoch: u64,
    voter_pubkey: Pubkey,
) -> Vec<u8> {
    let state = scout_create_canonical_stake_state_address(program_id);
    let stake_deposit_authority =
        Pubkey::find_program_address(&[state.as_ref(), SCOUT_STAKE_DEPOSIT_SEED], &program_id).0;
    let stake_withdraw_authority =
        Pubkey::find_program_address(&[state.as_ref(), SCOUT_STAKE_WITHDRAW_SEED], &program_id).0;
    let rent_exempt_reserve = account_lamports.saturating_sub(delegated_lamports);
    scout_deposit_stake_account_data(
        stake_deposit_authority,
        stake_withdraw_authority,
        voter_pubkey,
        delegated_lamports,
        rent_exempt_reserve,
        0,
        deactivation_epoch,
        solana_stake_interface::state::Lockup::default(),
    )
}

fn scout_write_create_canonical_state(
    f: &mut MarinadeFinanceFixture,
    paused: bool,
    delinquent_upgrader: marinade_finance::types::DelinquentUpgraderState,
) {
    let data = scout_create_canonical_state_data(
        f.payer.pubkey(),
        f.program_id,
        paused,
        delinquent_upgrader,
    );
    f.ctx
        .create_account()
        .pubkey(scout_create_canonical_stake_state_address(f.program_id))
        .owner(f.program_id)
        .data(&data)
        .create()
        .unwrap();
}

fn scout_write_create_canonical_stake_list(
    f: &mut MarinadeFinanceFixture,
    delegated_lamports: u64,
) {
    let data = scout_create_canonical_stake_list_data(f.program_id, delegated_lamports, 0);
    f.ctx
        .create_account()
        .pubkey(scout_create_canonical_stake_list_address(f.program_id))
        .owner(f.program_id)
        .data(&data)
        .create()
        .unwrap();
}

fn scout_write_create_canonical_source_stake(
    f: &mut MarinadeFinanceFixture,
    delegated_lamports: u64,
    account_lamports: u64,
    deactivation_epoch: u64,
    voter_pubkey: Pubkey,
) {
    let data = scout_create_canonical_source_stake_data(
        f.program_id,
        delegated_lamports,
        account_lamports,
        deactivation_epoch,
        voter_pubkey,
    );
    f.ctx
        .create_account()
        .pubkey(scout_create_canonical_source_stake_address(f.program_id))
        .owner(solana_stake_interface::program::ID)
        .lamports(account_lamports)
        .data(&data)
        .create()
        .unwrap();
}

