const SCOUT_DEACTIVATE_STAKE_LAMPORTS: u64 = 50_000_000;
const SCOUT_DEACTIVATE_VALIDATOR_SCORE: u32 = 100;

fn scout_deactivate_derived_pubkey(state: Pubkey, tag: u8) -> Pubkey {
    let mut bytes = state.to_bytes();
    bytes[0] ^= tag;
    bytes[31] = bytes[31].wrapping_add(tag);
    Pubkey::new_from_array(bytes)
}

fn scout_deactivate_stake_list_key(state: Pubkey) -> Pubkey {
    scout_deactivate_derived_pubkey(state, 0xd5)
}

fn scout_deactivate_stake_account_key(state: Pubkey) -> Pubkey {
    scout_deactivate_derived_pubkey(state, 0xda)
}

fn scout_deactivate_validator_vote_key(state: Pubkey) -> Pubkey {
    scout_deactivate_derived_pubkey(state, 0xdb)
}

fn scout_deactivate_stake_record_data(
    stake_account: Pubkey,
    delegated_lamports: u64,
    epoch: u64,
) -> Vec<u8> {
    let record = marinade_finance::types::StakeRecord {
        stake_account,
        last_update_delegated_lamports: delegated_lamports,
        last_update_epoch: epoch,
        is_emergency_unstaking: false,
        last_update_status: marinade_finance::types::StakeStatus::Active,
    };
    let mut data = Vec::new();
    record.serialize(&mut data).unwrap();
    data
}

fn scout_deactivate_stake_list_data(
    stake_account: Pubkey,
    delegated_lamports: u64,
    epoch: u64,
) -> Vec<u8> {
    let record_data = scout_deactivate_stake_record_data(stake_account, delegated_lamports, epoch);
    let mut data = SCOUT_STAKE_LIST_DISCRIMINATOR.to_vec();
    data.extend_from_slice(&record_data);
    data.resize(8 + record_data.len() * SCOUT_STAKE_LIST_CAPACITY, 0);
    data
}

fn scout_deactivate_validator_list_data(
    validator_vote: Pubkey,
    state: Pubkey,
    program_id: Pubkey,
    active_balance: u64,
) -> Vec<u8> {
    let (_duplication_flag, duplication_flag_bump_seed) = Pubkey::find_program_address(
        &[state.as_ref(), SCOUT_DUPLICATE_FLAG_SEED, validator_vote.as_ref()],
        &program_id,
    );
    let record = marinade_finance::types::ValidatorRecord {
        validator_account: validator_vote,
        active_balance,
        score: SCOUT_DEACTIVATE_VALIDATOR_SCORE,
        last_stake_delta_epoch: u64::MAX,
        duplication_flag_bump_seed,
        delinquent_upgrader_active_balance: 0,
    };
    scout_validator_list_data(&[record])
}

fn scout_deactivate_native_stake_account_data(
    stake_deposit_authority: Pubkey,
    validator_vote: Pubkey,
    delegated_lamports: u64,
) -> Vec<u8> {
    let stake_state = solana_stake_interface::state::StakeStateV2::Stake(
        solana_stake_interface::state::Meta {
            rent_exempt_reserve: 0,
            authorized: solana_stake_interface::state::Authorized::auto(
                &stake_deposit_authority,
            ),
            lockup: solana_stake_interface::state::Lockup::default(),
        },
        solana_stake_interface::state::Stake {
            delegation: solana_stake_interface::state::Delegation {
                voter_pubkey: validator_vote,
                stake: delegated_lamports,
                activation_epoch: 0,
                deactivation_epoch: u64::MAX,
                warmup_cooldown_rate:
                    solana_stake_interface::state::DEFAULT_WARMUP_COOLDOWN_RATE,
            },
            credits_observed: 0,
        },
        solana_stake_interface::stake_flags::StakeFlags::empty(),
    );
    let mut data = Vec::new();
    stake_state.serialize(&mut data).unwrap();
    data.resize(solana_stake_interface::state::StakeStateV2::size_of(), 0);
    data
}

