    let (liq_pool_msol_leg_authority, msol_leg_authority_bump_seed) = Pubkey::find_program_address(
        &[f.state.as_ref(), SCOUT_LIQ_POOL_MSOL_LEG_AUTHORITY_SEED],
        &f.program_id,
    );
    let (reserve_pda, reserve_bump_seed) =
        Pubkey::find_program_address(&[f.state.as_ref(), SCOUT_RESERVE_SEED], &f.program_id);
    let (msol_mint_authority, msol_mint_authority_bump_seed) =
        Pubkey::find_program_address(&[f.state.as_ref(), SCOUT_MSOL_MINT_AUTHORITY_SEED], &f.program_id);

    f.liq_pool_sol_leg_pda = liq_pool_sol_leg_pda;
    f.liq_pool_msol_leg_authority = liq_pool_msol_leg_authority;
    f.reserve_pda = reserve_pda;
    f.msol_mint_authority = msol_mint_authority;

    let mut state_value = f
        .ctx
        .read_anchor_account::<marinade_finance::state::State>(&f.state)
        .unwrap_or_else(|_| {
            scout_deposit_stake_state(
                f,
                false,
                u64::MAX,
                1,
                0,
                marinade_finance::types::DelinquentUpgraderState::Done,
            )
        });
    state_value.msol_mint = f.msol_mint;
    state_value.reserve_bump_seed = reserve_bump_seed;
    state_value.msol_mint_authority_bump_seed = msol_mint_authority_bump_seed;
    state_value.liq_pool.sol_leg_bump_seed = sol_leg_bump_seed;
    state_value.liq_pool.msol_leg_authority_bump_seed = msol_leg_authority_bump_seed;
    state_value.liq_pool.msol_leg = f.liq_pool_msol_leg;
    state_value.available_reserve_balance = 0;
    state_value.msol_supply = 0;
    state_value.min_deposit = 1;
    state_value.staking_sol_cap = u64::MAX;
    state_value.paused = false;
    state_value.deposit_sol_fee = marinade_finance::types::FeeCents { bp_cents: 0 };
    state_value.delinquent_upgrader = marinade_finance::types::DelinquentUpgraderState::Done;
    let state_data = scout_state_data(&state_value);
    f.ctx
        .create_account()
        .pubkey(f.state)
        .owner(f.program_id)
        .data(&state_data)
        .create()
        .unwrap();

    f.ctx
        .create_mint()
        .pubkey(f.msol_mint)
        .mint_authority(msol_mint_authority)
        .supply(0)
        .decimals(9)
        .freeze_authority(None)
        .create()
        .unwrap();
    f.ctx
        .create_token_account()
        .pubkey(f.liq_pool_msol_leg)
        .mint(f.msol_mint)
        .token_owner(liq_pool_msol_leg_authority)
        .amount(SCOUT_DEPOSIT_LIQ_POOL_MSOL_BALANCE)
        .create()
        .unwrap();
    f.ctx
        .create_token_account()
        .pubkey(f.mint_to)
        .mint(f.msol_mint)
        .token_owner(f.payer.pubkey())
        .amount(0)
        .create()
        .unwrap();
    f.ctx
        .create_account()
        .pubkey(liq_pool_sol_leg_pda)
        .owner(system_program::ID)
