const SCOUT_STAKE_RESERVE_STAKE_LAMPORTS: u64 = 2_000_000_000;
const SCOUT_STAKE_RESERVE_VOTE_STATE_SIZE: usize = 3762;

fn scout_stake_reserve_vote_program_id() -> Pubkey {
    <Pubkey as std::str::FromStr>::from_str("Vote111111111111111111111111111111111111111")
        .unwrap()
}

fn scout_stake_reserve_vote_state_v4_data() -> Vec<u8> {
    let mut data = vec![0u8; SCOUT_STAKE_RESERVE_VOTE_STATE_SIZE];
    data[..4].copy_from_slice(&3u32.to_le_bytes());
    data
}

fn scout_stake_reserve_end_epoch_clock() -> anchor_lang::solana_program::clock::Clock {
    anchor_lang::solana_program::clock::Clock {
        slot: 2 * 432_000 + 431_999,
        epoch_start_timestamp: 10_000,
        epoch: 2,
        leader_schedule_epoch: 2,
        unix_timestamp: 20_000,
    }
}

fn scout_prepare_stake_reserve_positive_path(fixture: &mut MarinadeFinanceFixture) {
    let mut state = scout_read_marinade_state(&fixture.ctx, &fixture.state);
    let mut stake_list = state.stake_system.stake_list.account;
    if stake_list == Pubkey::default() {
        stake_list = Pubkey::find_program_address(
            &[fixture.state.as_ref(), b"scout_stake_reserve_stake_list"],
            &fixture.program_id,
        )
        .0;
    }
    let reserve_pda =
        Pubkey::find_program_address(&[fixture.state.as_ref(), SCOUT_RESERVE_SEED], &fixture.program_id).0;
    let (validator_record, _duplication_flag, _duplication_flag_bump_seed) =
        scout_validator_record(
            fixture.state,
            fixture.validator_vote,
            fixture.program_id,
            SCOUT_STAKE_RESERVE_VALIDATOR_SCORE,
        );

    state.available_reserve_balance = SCOUT_STAKE_RESERVE_STAKE_LAMPORTS;
    state.circulating_ticket_balance = 0;
    state.emergency_cooling_down = 0;
    state.rent_exempt_for_token_acc = 0;
    state.stake_system.delayed_unstake_cooling_down = 0;
    state.stake_system.last_stake_delta_epoch = u64::MAX;
    state.stake_system.extra_stake_delta_runs = 0;
    state.stake_system.slots_for_stake_delta = u64::MAX;
    state.stake_system.min_stake = 10_000_000;
    state.stake_system.stake_list = scout_list(stake_list, SCOUT_STAKE_RECORD_SIZE, 0);
    state.validator_system.validator_list = scout_list(
        fixture.validator_list,
        SCOUT_VALIDATOR_RECORD_SIZE,
        1,
    );
    state.validator_system.total_validator_score = SCOUT_STAKE_RESERVE_VALIDATOR_SCORE;
    state.validator_system.total_active_balance = 0;
    state.delinquent_upgrader = marinade_finance::types::DelinquentUpgraderState::Done;
    scout_write_marinade_state(&mut fixture.ctx, fixture.state, &state);

    let mut validator_list_data = scout_validator_list_data(&[validator_record]);
    validator_list_data.resize(
        8 + SCOUT_VALIDATOR_RECORD_SIZE * SCOUT_VALIDATOR_LIST_CAPACITY,
        0,
    );
    if let Ok(mut validator_list_account) = fixture.ctx.read_account(&fixture.validator_list) {
        validator_list_account.owner = fixture.program_id;
        validator_list_account.data = validator_list_data;
        fixture.ctx.write_account(&fixture.validator_list, validator_list_account).unwrap();
    } else {
        fixture
            .ctx
            .create_account()
            .pubkey(fixture.validator_list)
            .owner(fixture.program_id)
            .data(&validator_list_data)
            .create()
            .unwrap();
    }

    let mut stake_list_data = SCOUT_STAKE_LIST_DISCRIMINATOR.to_vec();
    stake_list_data.resize(
        8 + SCOUT_STAKE_RECORD_SIZE * SCOUT_STAKE_LIST_CAPACITY,
        0,
    );
    if let Ok(mut stake_list_account) = fixture.ctx.read_account(&stake_list) {
        stake_list_account.owner = fixture.program_id;
        stake_list_account.data = stake_list_data;
        fixture.ctx.write_account(&stake_list, stake_list_account).unwrap();
    } else {
        fixture
            .ctx
            .create_account()
            .pubkey(stake_list)
            .owner(fixture.program_id)
            .data(&stake_list_data)
            .create()
            .unwrap();
    }

    if let Ok(mut reserve_account) = fixture.ctx.read_account(&reserve_pda) {
        reserve_account.owner = system_program::ID;
        reserve_account.lamports = SCOUT_STAKE_RESERVE_STAKE_LAMPORTS;
        reserve_account.data.clear();
        fixture.ctx.write_account(&reserve_pda, reserve_account).unwrap();
    } else {
        fixture
            .ctx
            .create_account()
            .pubkey(reserve_pda)
            .owner(system_program::ID)
            .lamports(SCOUT_STAKE_RESERVE_STAKE_LAMPORTS)
            .create()
            .unwrap();
    }

    if let Ok(mut vote_account) = fixture.ctx.read_account(&fixture.validator_vote) {
        vote_account.owner = scout_stake_reserve_vote_program_id();
        vote_account.lamports = vote_account.lamports.max(1_000_000_000);
        vote_account.data = scout_stake_reserve_vote_state_v4_data();
        fixture.ctx.write_account(&fixture.validator_vote, vote_account).unwrap();
    } else {
        fixture
            .ctx
            .create_account()
            .pubkey(fixture.validator_vote)
            .owner(scout_stake_reserve_vote_program_id())
            .lamports(1_000_000_000)
            .data(&scout_stake_reserve_vote_state_v4_data())
            .create()
            .unwrap();
    }

    fixture.ctx.set_sysvar(&scout_stake_reserve_end_epoch_clock());
}
fn scout_prepare_stake_reserve_action_preserving_primary_guards(fixture: &mut MarinadeFinanceFixture) {
    let original = scout_read_marinade_state(&fixture.ctx, &fixture.state);
    let paused = original.paused;
    let delinquent_upgrader = original.delinquent_upgrader.clone();
    scout_prepare_stake_reserve_positive_path(fixture);
    let mut prepared = scout_read_marinade_state(&fixture.ctx, &fixture.state);
    prepared.paused = paused;
    prepared.delinquent_upgrader = delinquent_upgrader;
    scout_write_marinade_state(&mut fixture.ctx, fixture.state, &prepared);
}
