fn scout_dsa_append_state_account(
    authority: Pubkey,
    program_id: Pubkey,
) -> marinade_finance::state::State {
    let state = scout_dsa_append_state(program_id);
    let validator_list = scout_dsa_append_validator_list(program_id);
    let stake_list = scout_dsa_append_stake_list(program_id);
    let msol_mint = scout_dsa_append_msol_mint(program_id);
    let (_reserve, reserve_bump_seed) =
        Pubkey::find_program_address(&[state.as_ref(), SCOUT_RESERVE_SEED], &program_id);
    let (_msol_mint_authority, msol_mint_authority_bump_seed) =
        Pubkey::find_program_address(&[state.as_ref(), SCOUT_MSOL_MINT_AUTHORITY_SEED], &program_id);
    let (_stake_deposit_authority, stake_deposit_bump_seed) =
        Pubkey::find_program_address(&[state.as_ref(), SCOUT_STAKE_DEPOSIT_SEED], &program_id);
    let (_stake_withdraw_authority, stake_withdraw_bump_seed) =
        Pubkey::find_program_address(&[state.as_ref(), SCOUT_STAKE_WITHDRAW_SEED], &program_id);
    let (_lp_mint_authority, lp_mint_authority_bump_seed) =
        Pubkey::find_program_address(&[state.as_ref(), SCOUT_LP_MINT_AUTHORITY_SEED], &program_id);
    let (_liq_pool_sol_leg, sol_leg_bump_seed) =
        Pubkey::find_program_address(&[state.as_ref(), SCOUT_LIQ_POOL_SOL_LEG_SEED], &program_id);
    let (_liq_pool_msol_leg_authority, msol_leg_authority_bump_seed) =
        Pubkey::find_program_address(
            &[state.as_ref(), SCOUT_LIQ_POOL_MSOL_LEG_AUTHORITY_SEED],
            &program_id,
        );
    let zero_fee = marinade_finance::types::Fee { basis_points: 0 };
    let zero_fee_cents = marinade_finance::types::FeeCents { bp_cents: 0 };

    marinade_finance::state::State {
        msol_mint,
        admin_authority: authority,
        operational_sol_account: authority,
        treasury_msol_account: Pubkey::new_unique(),
        reserve_bump_seed,
        msol_mint_authority_bump_seed,
        rent_exempt_for_token_acc: 0,
        reward_fee: zero_fee,
        stake_system: marinade_finance::types::StakeSystem {
            stake_list: marinade_finance::types::List {
                account: stake_list,
                item_size: SCOUT_STAKE_RECORD_SIZE as u32,
                count: 0,
                reserved1: Pubkey::default(),
                reserved2: 0,
            },
            delayed_unstake_cooling_down: 0,
            stake_deposit_bump_seed,
            stake_withdraw_bump_seed,
            slots_for_stake_delta: 3_000,
            last_stake_delta_epoch: u64::MAX,
            min_stake: 10_000_000,
            extra_stake_delta_runs: 0,
        },
        validator_system: marinade_finance::types::ValidatorSystem {
            validator_list: marinade_finance::types::List {
                account: validator_list,
                item_size: SCOUT_VALIDATOR_RECORD_SIZE as u32,
                count: 1,
                reserved1: Pubkey::default(),
                reserved2: 0,
            },
            manager_authority: authority,
            total_validator_score: SCOUT_INITIAL_VALIDATOR_SCORE,
            total_active_balance: 0,
            auto_add_validator_enabled: 0,
        },
        liq_pool: marinade_finance::types::LiqPool {
            lp_mint: Pubkey::new_unique(),
            lp_mint_authority_bump_seed,
            sol_leg_bump_seed,
            msol_leg_authority_bump_seed,
            msol_leg: Pubkey::new_unique(),
            lp_liquidity_target: 50_000_000_000,
            lp_max_fee: marinade_finance::types::Fee { basis_points: 300 },
            lp_min_fee: marinade_finance::types::Fee { basis_points: 30 },
            treasury_cut: marinade_finance::types::Fee { basis_points: 2500 },
            lp_supply: 0,
            lent_from_sol_leg: 0,
            liquidity_sol_cap: u64::MAX,
        },
        available_reserve_balance: 0,
        msol_supply: 0,
        msol_price: 0x1_0000_0000,
        circulating_ticket_count: 0,
        circulating_ticket_balance: 0,
        lent_from_reserve: 0,
        min_deposit: 1,
        min_withdraw: 1,
        staking_sol_cap: u64::MAX,
        emergency_cooling_down: 0,
        pause_authority: authority,
        paused: false,
        delayed_unstake_fee: zero_fee_cents,
        withdraw_stake_account_fee: zero_fee_cents,
        withdraw_stake_account_enabled: false,
        last_stake_move_epoch: 0,
        stake_moved: 0,
        max_stake_moved_per_epoch: marinade_finance::types::Fee {
            basis_points: 10_000,
        },
        delinquent_upgrader: marinade_finance::types::DelinquentUpgraderState::Done,
        deposit_sol_fee: zero_fee_cents,
        deposit_stake_account_fee: zero_fee_cents,
    }
}

