    let msol_mint = scout_withdraw_msol_mint_pubkey(f.program_id);
    let treasury_msol_account = scout_withdraw_treasury_msol_account_pubkey(f.program_id);

    let mut state_account = f
        .ctx
        .read_anchor_account::<marinade_finance::state::State>(&state)
        .unwrap();
    state_account.withdraw_stake_account_fee = marinade_finance::types::FeeCents { bp_cents: 100_000 };
