fn scout_prepare_merge_stakes_active_rent(fixture: &mut MarinadeFinanceFixture) {
    let state = scout_merge_state_pubkey();
    let stake_list = scout_merge_stake_list_pubkey();
    let validator_list = scout_merge_validator_list_pubkey();
    let validator_vote = scout_merge_validator_vote_pubkey();
    let destination_stake = scout_merge_destination_stake_pubkey(&fixture.program_id);
    let source_stake = scout_merge_source_stake_pubkey();
    let stake_deposit_authority =
        Pubkey::find_program_address(&[state.as_ref(), SCOUT_STAKE_DEPOSIT_SEED], &fixture.program_id).0;
    let stake_withdraw_authority =
        Pubkey::find_program_address(&[state.as_ref(), SCOUT_STAKE_WITHDRAW_SEED], &fixture.program_id).0;
    let state_account = scout_merge_state_account(
        fixture.payer.pubkey(),
        fixture.program_id,
        state,
        stake_list,
        validator_list,
        scout_merge_operational_sol_account_pubkey(),
    );
    fixture.ctx.create_account()
        .pubkey(state)
        .owner(fixture.program_id)
        .data(&scout_state_data(&state_account))
        .create()
        .unwrap();
    fixture.ctx.create_account()
        .pubkey(stake_list)
        .owner(fixture.program_id)
        .data(&scout_merge_stake_list_data(destination_stake, source_stake))
        .create()
        .unwrap();
    fixture.ctx.create_account()
        .pubkey(validator_list)
        .owner(fixture.program_id)
        .data(&scout_merge_validator_list_data(state, validator_vote, fixture.program_id))
        .create()
        .unwrap();
    fixture.ctx.create_account()
        .pubkey(destination_stake)
        .owner(solana_stake_interface::program::ID)
        .lamports(SCOUT_MERGE_DESTINATION_STAKE_LAMPORTS + SCOUT_MERGE_STAKE_RENT_LAMPORTS)
        .data(&scout_deposit_stake_account_data(
            stake_deposit_authority,
            stake_withdraw_authority,
            validator_vote,
            SCOUT_MERGE_DESTINATION_STAKE_LAMPORTS,
            SCOUT_MERGE_STAKE_RENT_LAMPORTS,
            0,
            u64::MAX,
            solana_stake_interface::state::Lockup::default(),
        ))
        .create()
        .unwrap();
    fixture.ctx.create_account()
        .pubkey(source_stake)
        .owner(solana_stake_interface::program::ID)
        .lamports(SCOUT_MERGE_SOURCE_STAKE_LAMPORTS + SCOUT_MERGE_STAKE_RENT_LAMPORTS)
        .data(&scout_deposit_stake_account_data(
            stake_deposit_authority,
            stake_withdraw_authority,
            validator_vote,
            SCOUT_MERGE_SOURCE_STAKE_LAMPORTS,
            SCOUT_MERGE_STAKE_RENT_LAMPORTS,
            0,
            u64::MAX,
            solana_stake_interface::state::Lockup::default(),
        ))
        .create()
        .unwrap();
    fixture.ctx.create_account()
        .pubkey(scout_merge_operational_sol_account_pubkey())
        .owner(system_program::ID)
        .lamports(1_000_000)
        .create()
        .unwrap();
    fixture.ctx.set_sysvar(&scout_claim_clock(2, 3_600));
}

