fn scout_dsa_append_write_or_create_account(
    fixture: &mut MarinadeFinanceFixture,
    pubkey: Pubkey,
    owner: Pubkey,
    lamports: u64,
    data: Vec<u8>,
) {
    if let Ok(mut account) = fixture.ctx.read_account(&pubkey) {
        account.owner = owner;
        account.lamports = lamports;
        account.data = data;
        fixture.ctx.write_account(&pubkey, account).unwrap();
    } else {
        fixture.ctx.create_account()
            .pubkey(pubkey)
            .owner(owner)
            .lamports(lamports)
            .data(&data)
            .create()
            .unwrap();
    }
}

fn scout_dsa_append_mint_data(mint_authority: Pubkey, supply: u64) -> Vec<u8> {
    let mint = crucible_fuzzer::anchor_spl::token::spl_token::state::Mint {
        mint_authority: crucible_fuzzer::anchor_lang::solana_program::program_option::COption::Some(mint_authority),
        supply,
        decimals: 9,
        is_initialized: true,
        freeze_authority: crucible_fuzzer::anchor_lang::solana_program::program_option::COption::None,
    };
    let mut data = vec![
        0u8;
        <crucible_fuzzer::anchor_spl::token::spl_token::state::Mint as crucible_fuzzer::anchor_lang::solana_program::program_pack::Pack>::LEN
    ];
    <crucible_fuzzer::anchor_spl::token::spl_token::state::Mint as crucible_fuzzer::anchor_lang::solana_program::program_pack::Pack>::pack(
        mint,
        &mut data,
    )
    .unwrap();
    data
}

fn scout_dsa_append_token_account_data(mint: Pubkey, owner: Pubkey, amount: u64) -> Vec<u8> {
    let mut token_account = crucible_fuzzer::anchor_spl::token::spl_token::state::Account::default();
    token_account.mint = mint;
    token_account.owner = owner;
    token_account.amount = amount;
    token_account.state = crucible_fuzzer::anchor_spl::token::spl_token::state::AccountState::Initialized;
    let mut data = vec![
        0u8;
        <crucible_fuzzer::anchor_spl::token::spl_token::state::Account as crucible_fuzzer::anchor_lang::solana_program::program_pack::Pack>::LEN
    ];
    <crucible_fuzzer::anchor_spl::token::spl_token::state::Account as crucible_fuzzer::anchor_lang::solana_program::program_pack::Pack>::pack(
        token_account,
        &mut data,
    )
    .unwrap();
    data
}

fn scout_prepare_deposit_stake_account_append_fixture_replayable(
    fixture: &mut MarinadeFinanceFixture,
) {
    let state = scout_dsa_append_state(fixture.program_id);
    let validator_list = scout_dsa_append_validator_list(fixture.program_id);
    let stake_list = scout_dsa_append_stake_list(fixture.program_id);
    let stake_account = scout_dsa_append_stake_account(fixture.program_id);
    let validator_vote = scout_dsa_append_validator_vote(fixture.program_id);
    let msol_mint = scout_dsa_append_msol_mint(fixture.program_id);
    let mint_to = scout_dsa_append_mint_to(fixture.program_id);
    let duplication_flag = scout_dsa_append_duplication_flag(fixture.program_id);
    let (msol_mint_authority, _) = Pubkey::find_program_address(
        &[state.as_ref(), SCOUT_MSOL_MINT_AUTHORITY_SEED],
        &fixture.program_id,
    );
    let validator_record =
        scout_deposit_stake_validator_record(state, validator_vote, fixture.program_id);
    let state_account = scout_dsa_append_state_account(fixture.payer.pubkey(), fixture.program_id);
    let state_data = scout_anchor_account_data(
        marinade_finance::state::State::DISCRIMINATOR,
        &state_account,
    );
    let stake_data = scout_deposit_stake_account_data(
        fixture.payer.pubkey(),
        fixture.payer.pubkey(),
        validator_vote,
        SCOUT_DSA_APPEND_STAKE_LAMPORTS,
        0,
        0,
        u64::MAX,
        solana_stake_interface::state::Lockup::default(),
    );

    scout_dsa_append_write_or_create_account(
        fixture,
        state,
        fixture.program_id,
        1_000_000,
        state_data,
    );
    scout_dsa_append_write_or_create_account(
        fixture,
        validator_list,
        fixture.program_id,
        1_000_000,
        scout_validator_list_data(&[validator_record]),
    );
    scout_dsa_append_write_or_create_account(
        fixture,
        stake_list,
        fixture.program_id,
        1_000_000,
        scout_deposit_stake_list_data(),
    );
    scout_dsa_append_write_or_create_account(
        fixture,
        stake_account,
        solana_stake_interface::program::ID,
        SCOUT_DSA_APPEND_STAKE_LAMPORTS,
        stake_data,
    );
    scout_dsa_append_write_or_create_account(
        fixture,
        duplication_flag,
        system_program::ID,
        1_000_000,
        Vec::new(),
    );
    scout_dsa_append_write_or_create_account(
        fixture,
        msol_mint_authority,
        system_program::ID,
        1_000_000,
        Vec::new(),
    );
    scout_dsa_append_write_or_create_account(
        fixture,
        msol_mint,
        crucible_fuzzer::anchor_spl::token::ID,
        1_000_000,
        scout_dsa_append_mint_data(msol_mint_authority, 0),
    );
    scout_dsa_append_write_or_create_account(
        fixture,
        mint_to,
        crucible_fuzzer::anchor_spl::token::ID,
        1_000_000,
        scout_dsa_append_token_account_data(msol_mint, fixture.payer.pubkey(), 0),
    );
}

fn scout_prepare_emergency_unstake_rent_backed(f: &mut MarinadeFinanceFixture) {
    let state = scout_emergency_unstake_state(f.program_id);
    let validator_list = scout_emergency_unstake_validator_list(f.program_id);
    let stake_list = scout_emergency_unstake_stake_list(f.program_id);
    let stake_account = scout_emergency_unstake_stake_account(f.program_id);
    let validator_vote = scout_emergency_unstake_validator_vote(f.program_id);
    let stake_deposit_authority =
        Pubkey::find_program_address(&[state.as_ref(), SCOUT_STAKE_DEPOSIT_SEED], &f.program_id).0;
    let rent_exempt_reserve = f
        .ctx
        .svm
        .minimum_balance_for_rent_exemption(solana_stake_interface::state::StakeStateV2::size_of());
    let state_account = scout_emergency_unstake_state_account(
        f.payer.pubkey(),
        f.program_id,
        false,
        marinade_finance::types::DelinquentUpgraderState::Done,
        0,
        SCOUT_EMERGENCY_UNSTAKE_AMOUNT,
        10_000,
    );
    f.ctx
        .create_account()
        .pubkey(state)
        .owner(f.program_id)
        .data(&scout_state_data(&state_account))
        .create()
        .unwrap();
    f.ctx
        .create_account()
        .pubkey(validator_list)
        .owner(f.program_id)
        .data(&scout_emergency_unstake_validator_record_data(
            state,
            validator_vote,
            SCOUT_EMERGENCY_UNSTAKE_AMOUNT,
            0,
            f.program_id,
        ))
        .create()
        .unwrap();
    f.ctx
        .create_account()
        .pubkey(stake_list)
        .owner(f.program_id)
        .data(&scout_emergency_unstake_stake_record_data(
            stake_account,
            SCOUT_EMERGENCY_UNSTAKE_AMOUNT,
            marinade_finance::types::StakeStatus::Active,
            false,
        ))
        .create()
        .unwrap();
    f.ctx
        .create_account()
        .pubkey(stake_account)
        .owner(solana_stake_interface::program::ID)
        .lamports(rent_exempt_reserve + SCOUT_EMERGENCY_UNSTAKE_AMOUNT)
        .data(&scout_deposit_stake_account_data(
            stake_deposit_authority,
            stake_deposit_authority,
            validator_vote,
            SCOUT_EMERGENCY_UNSTAKE_AMOUNT,
            rent_exempt_reserve,
            0,
            u64::MAX,
            solana_stake_interface::state::Lockup::default(),
        ))
        .create()
        .unwrap();
    f.ctx
        .create_account()
        .pubkey(validator_vote)
        .owner(system_program::ID)
        .data(&[1])
        .create()
        .unwrap();
    // set_epoch_stake was removed from crucible-test-context (API drift); this was a
    // discarded best-effort setup call for emergency_unstake (itself CPI-walled). Dropped
    // to restore compilation against the current crucible checkout.
    let _ = SCOUT_EMERGENCY_UNSTAKE_AMOUNT;
}
