fn scout_dsa_isolated_setup(f: &mut MarinadeFinanceFixture) {
    let program_id = f.program_id;
    let payer = f.payer.pubkey();
    let dsa_state = f.dsa_state;
    let dsa_validator_list = f.dsa_validator_list;
    let dsa_msol_mint = f.dsa_msol_mint;
    let dsa_mint_to = f.dsa_mint_to;
    let dsa_validator_vote = Pubkey::new_unique();
    let (msol_mint_authority, _) = Pubkey::find_program_address(
        &[dsa_state.as_ref(), SCOUT_MSOL_MINT_AUTHORITY_SEED],
        &program_id,
    );

    let state_value =
        scout_dsa_isolated_state(dsa_state, dsa_validator_list, dsa_msol_mint, payer, program_id);
    let state_data =
        scout_anchor_account_data(marinade_finance::state::State::DISCRIMINATOR, &state_value);
    f.ctx
        .create_account()
        .pubkey(dsa_state)
        .owner(program_id)
        .data(&state_data)
        .create()
        .unwrap();

    let validator_record =
        scout_deposit_stake_validator_record(dsa_state, dsa_validator_vote, program_id);
    let validator_list_data = scout_validator_list_data(&[validator_record]);
    f.ctx
        .create_account()
        .pubkey(dsa_validator_list)
        .owner(program_id)
        .data(&validator_list_data)
        .create()
        .unwrap();

    let stake_list_data = scout_deposit_stake_list_data();
    f.ctx
        .create_account()
        .pubkey(scout_deposit_stake_list_address(dsa_state, program_id))
        .owner(program_id)
        .data(&stake_list_data)
        .create()
        .unwrap();

    f.ctx
        .create_mint()
        .pubkey(dsa_msol_mint)
        .mint_authority(msol_mint_authority)
        .supply(0)
        .decimals(9)
        .freeze_authority(None)
        .create()
        .unwrap();
    f.ctx
        .create_token_account()
        .pubkey(dsa_mint_to)
        .mint(dsa_msol_mint)
        .token_owner(payer)
        .amount(0)
        .create()
        .unwrap();

    f.ctx
        .create_account()
        .pubkey(scout_deposit_stake_duplication_flag_address(payer))
        .owner(system_program::ID)
        .create()
        .unwrap();

    let stake_data = scout_deposit_stake_account_data(
        payer,
        payer,
        dsa_validator_vote,
        SCOUT_DEPOSIT_STAKE_LAMPORTS,
        0,
        0,
        u64::MAX,
        solana_stake_interface::state::Lockup::default(),
    );
    f.ctx
        .create_account()
        .pubkey(scout_deposit_stake_account_address(dsa_state, program_id))
        .owner(solana_stake_interface::program::ID)
        .lamports(SCOUT_DEPOSIT_STAKE_LAMPORTS)
        .data(&stake_data)
        .create()
        .unwrap();
}

