const SCOUT_FORK_TREASURY_MSOL_ADDR: &str = "B1aLzaNMeFVAyQ6f3XbbUyKcH2YPHu2fqiEagmiF23VR";
const SCOUT_FORK_OPERATIONAL_ADDR: &str = "opLSF7LdfyWNBby5o6FT8UFsr2A4UGKteECgtLSYrSm";
