const SCOUT_FORK_STATE_BYTES: &[u8] = include_bytes!("../fixtures/mainnet/state.bin");
const SCOUT_FORK_MSOL_MINT_BYTES: &[u8] = include_bytes!("../fixtures/mainnet/msol_mint.bin");
