    pub fn action_change_authority(&mut self) -> bool {
        let data: marinade_finance::types::ChangeAuthorityData = { let __scout_n = self.scout_authority_toggle; self.scout_authority_toggle = self.scout_authority_toggle.wrapping_add(1); scout_change_authority_data(__scout_n, self.payer.pubkey()) };
        let state = self.state;
        let admin_authority = self.payer.pubkey();
        let __scout_success = self.ctx
            .program(self.program_id)
            .call(instruction::ChangeAuthority { data })
            .accounts(accounts::ChangeAuthority {
                state: state,
                admin_authority: admin_authority,
            })
            .signers(&[&*self.payer])
            .send()
            .map(|o| o.is_success())
            .unwrap_or(false);
        if __scout_success {
            // SCOUT:ACTION-HOOK:change_authority:BEGIN
            // update shadow-ledger state after successful change_authority
            // SCOUT:ACTION-HOOK:change_authority:END
        }
        __scout_success
    }

    pub fn action_add_validator(&mut self, score: u32) -> bool {
        // TODO: 1 extra signer(s): ['rent_payer']
        // Bound score to a realistic range: the unchecked `total_validator_score += score` u32
        // overflow is a recorded finding (bugs/marinade/02-*.md); cap the input so the fuzzer
        // stops re-flagging the KNOWN overflow and P-0007 can surface OTHER panics.
        // Under `repro_findings` (the fuzzcorp/all-bugs bundle) the clamp is lifted so the REAL
        // add_validator path reaches finding 02 organically (the fuzzer picks a large score and
        // `total_validator_score += score` overflows u32). Default build keeps the clamp.
        #[cfg(not(feature = "repro_findings"))]
        let score = score % 100_000;
        let state = self.state;
        let manager_authority = self.payer.pubkey();
        let validator_list = self.validator_list;
        let validator_vote = Pubkey::new_unique();
        let duplication_flag = Pubkey::find_program_address(&[state.as_ref(), SCOUT_DUPLICATE_FLAG_SEED, validator_vote.as_ref()], &self.program_id).0;
        let rent_payer = self.payer.pubkey();
        let clock = crucible_fuzzer::anchor_lang::solana_program::sysvar::clock::ID;
        let rent = crucible_fuzzer::anchor_lang::solana_program::sysvar::rent::ID;
        let system_program = system_program::ID;
        let __scout_success = self.ctx
            .program(self.program_id)
            .call(instruction::AddValidator { score })
            .accounts(accounts::AddValidator {
                state: state,
                manager_authority: manager_authority,
                validator_list: validator_list,
                validator_vote: validator_vote,
                duplication_flag: duplication_flag,
                rent_payer: rent_payer,
                clock: clock,
                rent: rent,
                system_program: system_program,
            })
            .signers(&[&*self.payer])
            .send()
            .map(|o| o.is_success())
            .unwrap_or(false);
        if __scout_success {
            // SCOUT:ACTION-HOOK:add_validator:BEGIN
            // update shadow-ledger state after successful add_validator
            // SCOUT:ACTION-HOOK:add_validator:END
        }
        __scout_success
    }

