    pub fn action_set_validator_score(&mut self, score: u32, index: u32) -> bool {
        // Bound score: the total_validator_score u32 overflow is a recorded finding
        // (bugs/marinade/02-*.md); cap so the fuzzer stops re-flagging it and P-0007 finds others.
        // Lifted under `repro_findings` so the fuzzcorp bundle reaches finding 02 organically.
        #[cfg(not(feature = "repro_findings"))]
        let score = score % 100_000;
        let validator_vote: Pubkey = self.validator_vote;
        let state = self.state;
        let manager_authority = self.payer.pubkey();
        let validator_list = self.validator_list;
        let __scout_success = self.ctx
            .program(self.program_id)
            .call(instruction::SetValidatorScore { index, validator_vote, score })
            .accounts(accounts::SetValidatorScore {
                state: state,
                manager_authority: manager_authority,
                validator_list: validator_list,
            })
            .signers(&[&*self.payer])
            .send()
            .map(|o| o.is_success())
            .unwrap_or(false);
        if __scout_success {
            // SCOUT:ACTION-HOOK:set_validator_score:BEGIN
            // update shadow-ledger state after successful set_validator_score
            // SCOUT:ACTION-HOOK:set_validator_score:END
        }
        __scout_success
    }

