        let reserve_pda = Pubkey::find_program_address(&[state.as_ref(), SCOUT_RESERVE_SEED], &self.program_id).0;
        let __scout_signer_stake_account = Keypair::new();
        let stake_account = __scout_signer_stake_account.pubkey();
        let stake_deposit_authority = Pubkey::find_program_address(&[state.as_ref(), SCOUT_STAKE_DEPOSIT_SEED], &self.program_id).0;
